 for(const pool of pools){const hit=pool.find(v=>{const raw=v?.division??v?.div??v?.name??v?.code??'';const m=String(raw).toUpperCase().match(/(?:^|[^0-9])(7|9|10)(?:[^0-9]|$)/);return m&&Number(m[1])===Number(n)});if(hit)return hit;}
