 if(v&&house(r.longitude,v.longitude)===1)hits.push(T('Rahu conjunct Venus','ராகு சுக்கிரனுடன் இணைவு'));
 if(!hits.length)return {level:0,hits:[],reasons:[],text:T('No Lagna-based Rahu–Ketu marriage-axis condition in this rule set','இந்த விதிகளில் லக்ன அடிப்படையிலான ராகு–கேது திருமண அச்சு நிலை இல்லை'),axis:false,moderated:false};
