 const moderated=protection>=2;const level=moderated?1:Math.min(2,hits.length+(axis?1:0));
 return {level,hits,reasons,axis,moderated,protection,rh,kh,text:`${hits.join(', ')}${reasons.length?' · '+T('Protection/context: ','பாதுகாப்பு/சூழல்: ')+reasons.join('; '):''}`};
