 const allRK=seven.every(([,x])=>inArc(r,arcRK,Number(x.longitude))),allKR=seven.every(([,x])=>inArc(k,arcKR,Number(x.longitude)));
 if(!allRK&&!allKR)return {state:'none',present:false,type:'',focus:'',focusHouse:null,modifiers:[],text:T('Kala Sarpa Yoga is not formed: all seven classical planets are not confined to one side of the Rahu–Ketu axis.','கால சர்ப்ப யோகம் இல்லை: ஏழு பாரம்பரிய கிரகங்களும் ராகு–கேது அச்சின் ஒரே பக்கத்தில் அடங்கவில்லை.')};
 // In normal zodiacal motion, planets on the Ketu→Rahu arc move toward Rahu (Anuloma); Rahu→Ketu gives Viloma.
 const type=allKR?'Anuloma':'Viloma',focus=type==='Anuloma'?P.Rahu:P.Ketu,fp=planet(c,focus),focusHouse=Number.isFinite(lag)&&fp?house(fp.longitude,lag):null;
 const modifiers=[];let relief=0,pressure=0;
 for(const node of [P.Rahu,P.Ketu]){const np=planet(c,node);if(!np)continue;const lord=LORD[si(np.longitude)],lp=planet(c,lord);if(lp){const dg=dignity(lord,lp.longitude);if(/Own|Exalted|சொந்த|உச்ச/.test(dg)){relief++;modifiers.push(T(`${mmPlanetEn(node)} sign lord ${mmPlanetEn(lord)} is strong`,`${mmPlanetTa(node)} இருக்கும் ராசியின் அதிபதி ${mmPlanetTa(lord)} நல்ல பலத்தில் உள்ளது`));}else if(/Debilitated|நீச/.test(dg)){pressure++;modifiers.push(T(`${mmPlanetEn(node)} sign lord ${mmPlanetEn(lord)} is debilitated`,`${mmPlanetTa(node)} இருக்கும் ராசியின் அதிபதி ${mmPlanetTa(lord)} நீச நிலையில் உள்ளது`));}}}
