 const state=pressure>relief?'active':relief>=pressure+2?'moderated':'mixed';
 const label=type==='Anuloma'?T('Anuloma Kala Sarpa pattern','அனுலோம கால சர்ப்ப அமைப்பு'):T('Viloma Kala Sarpa pattern','விலோம கால சர்ப்ப அமைப்பு');
