 const net=Math.max(0,raw-protect),state=raw<2?'none':net===0?'balanced':net>=6?'strong':net>=3?'active':'mild',level=state==='strong'?3:state==='active'?2:state==='mild'?1:0;
 const label=state==='none'?T('No significant Naga/Sarpa condition detected','குறிப்பிடத்தக்க நாக/சர்ப்ப அமைப்பு கண்டறியப்படவில்லை'):state==='balanced'?T('Initial indicators offset by protection — residual score 0','ஆரம்பக் குறிகள் ஆதரவால் குறைந்துள்ளன — மீதமுள்ள மதிப்பு 0'):state==='mild'?T('Low residual Naga/Sarpa indication','குறைந்த அளவு நாக/சர்ப்ப தாக்கம் மீதமுள்ளது'):state==='active'?T('Moderate residual Naga/Sarpa indication','மிதமான அளவு நாக/சர்ப்ப தாக்கம் மீதமுள்ளது'):T('Strong residual Naga/Sarpa indication','வலுவான நாக/சர்ப்ப தாக்கம் மீதமுள்ளது');
 const areaText=lang()==='ta'?[...areas].map(x=>({putra:'குழந்தை/புத்திரம்',marriage:'திருமணம்/உறவு',family:'குடும்பம்/கூட்டு வளம்',mind:'மனம்/உணர்ச்சி'})[x]).filter(Boolean).join(', '):[...areas].map(x=>({putra:'children/progeny',marriage:'marriage/relationship',family:'family/shared resources',mind:'mind/emotions'})[x]).filter(Boolean).join(', ');
