function dateMs(x){return mmDateMs(x);}
function gapDays(a,b){const as=dateMs(a.start),ae=dateMs(a.end),bs=dateMs(b.start),be=dateMs(b.end);if([as,ae,bs,be].some(Number.isNaN))return null;if(as<=be&&bs<=ae)return 0;return Math.round(Math.min(Math.abs(as-be),Math.abs(bs-ae))/86400000);}
function dashaDoshaSync(b,g){const bw=specialDashaWindows(b),gw=specialDashaWindows(g),bk=kujaAssessment(b),gk=kujaAssessment(g),br=rahuAssessment(b),gr=rahuAssessment(g),rows=[];const add=(who,dosha,planet,own,other,otherDosha)=>{if(!dosha.level)return;for(const a of own.filter(x=>x.planet===planet)){let best=null;for(const z of other.filter(x=>x.planet===planet)){const d=gapDays(a,z);if(d!=null&&(!best||d<best.d))best={z,d};}rows.push({who,planet,own:a,peer:best?.z||null,days:best?.d??null,peerDosha:otherDosha.level});}};add(T('Bride','பெண்'),bk,'Mars',bw,gw,gk);add(T('Groom','ஆண்'),gk,'Mars',gw,bw,bk);add(T('Bride','பெண்'),br,'Rahu',bw,gw,gr);add(T('Groom','ஆண்'),gr,'Rahu',gw,bw,br);return {rows,bk,gk,br,gr};}
function syncSeverity(sync){
  // Consolidate repeated MD/AD rows into one risk signal per planet. A single
  // Mars/Rahu condition must never be counted many times merely because the
  // same life period appears in several Mahadasha/Bhukti rows.
  const status={Mars:{overlap:false,near:false},Rahu:{overlap:false,near:false}};
  for(const x of sync.rows){
    if(!status[x.planet])continue;
    if(x.days===0&&x.peerDosha>0)status[x.planet].overlap=true;
    else if(x.days!=null&&x.days<=365)status[x.planet].near=true;
  }
  // Only unresolved natal dosha can activate verdict risk. Mitigated Kuja is
  // retained in the report but is not promoted to a major conflict here.
  const kujaUnresolved=(sync.bk.level>0&&!sync.bk.fullCancelled)||(sync.gk.level>0&&!sync.gk.fullCancelled);
  const rahuUnresolved=['active','complex'].includes(rahuVilakku(sync.br).state)||['active','complex'].includes(rahuVilakku(sync.gr).state);
  let severe=0,caution=0;
  if(status.Mars.overlap&&kujaUnresolved)caution++;
  else if(status.Mars.near&&kujaUnresolved)caution++;
  if(status.Rahu.overlap&&rahuUnresolved)caution++;
  else if(status.Rahu.near&&rahuUnresolved)caution++;
  return {severe,caution,status};
}
function renderDashaDosha(sync){const lines=sync.rows.map(x=>{const peer=x.peer?`${x.peer.label} ${x.peer.start} → ${x.peer.end}`:T('No corresponding period found in available range','கிடைத்த காலவரம்பில் இணையான காலம் இல்லை');const prox=x.days===0?T('OVERLAP','ஒரே காலத்தில் வருகிறது'):(x.days!=null?`${x.days} ${T('days apart','நாட்கள் இடைவெளி')}`:'—');return `<div><b>${esc(x.who)} · ${esc(x.planet)} ${T('Dasha–Dosha','தசா–தோஷம்')}</b><span>${esc(x.own.label)} ${esc(x.own.start)} → ${esc(x.own.end)}<br>${T('Other chart','மற்ற ஜாதகம்')}: ${esc(peer)} · ${esc(prox)} · ${T('corresponding dosha','தொடர்புடைய தோஷம்')}: ${x.peerDosha?T('present','உள்ளது'):T('not detected','கண்டறியப்படவில்லை')}</span></div>`}).join('');return `<section class="mm-person-result"><h3>${T('Dasha–Dosha Synchronisation','தசா–தோஷ ஒத்திசைவு')}</h3><div class="mm-facts"><div><b>${T('Bride Rahu–Ketu marriage-axis review','பெண் ராகு–கேது திருமண அச்சு ஆய்வு')}</b><span>${esc(sync.br.text)}</span></div><div><b>${T('Groom Rahu–Ketu marriage-axis review','ஆண் ராகு–கேது திருமண அச்சு ஆய்வு')}</b><span>${esc(sync.gr.text)}</span></div>${lines||`<div><b>${T('Result','முடிவு')}</b><span>${T('No Mars/Rahu dosha-linked period requiring synchronisation review was found.','செவ்வாய்/ராகு தோஷத்துடன் தொடர்புடைய தசா ஒத்திசைவு ஆய்வு தேவையான காலம் கிடைக்கவில்லை.')}</span></div>`}</div><p class="mm-note">${T('Mars or Rahu periods do not create a dosha by themselves. A Rahu period can only activate a residual natal Rahu–Ketu marriage-axis condition after protection/context checks. This section activates only when the natal chart first shows the stated Mars/Rahu affliction, then compares Mahadasha and Bhukti windows in both charts. Nearness/overlap is a review flag, not an automatic rejection.','செவ்வாய் அல்லது ராகு தசை மட்டும் தோஷத்தை உருவாக்காது. பாதுகாப்பு/சூழல் ஆய்வுக்குப் பிறகு மீதமுள்ள பிறப்பு ராகு–கேது திருமண அச்சு நிலையை மட்டுமே ராகு காலம் செயல்படுத்தும். ாது. பிறப்பு ஜாதகத்தில் குறிப்பிடப்பட்ட செவ்வாய்/ராகு பாதிப்பு முதலில் இருந்தால் மட்டுமே இந்த பகுதி செயல்பட்டு, இரு ஜாதகங்களின் மகாதசை மற்றும் புக்தி காலங்களை ஒப்பிடும். அருகாமை/ஒரே காலம் என்பது ஆய்வு குறியீடு மட்டுமே; தானாக நிராகரிப்பு அல்ல.')}</p></section>`;}
function dashaSandhi(a,b){const A=dashaPeriods(a),B=dashaPeriods(b),pairs=[];for(const x of A)for(const y of B){if(!x.end||!y.end)continue;const dx=new Date(String(x.end).includes('T')?x.end:x.end+'T00:00:00Z'),dy=new Date(String(y.end).includes('T')?y.end:y.end+'T00:00:00Z'),days=Math.abs(dx-dy)/86400000;if(days<=365)pairs.push({a:x,b:y,days:Math.round(days)});}pairs.sort((x,y)=>x.days-y.days);return pairs.slice(0,6);}


function mmAnalysisDate(){const raw=matchingTransit?.reviewDate||document.getElementById('mmGocharDate')?.value||new Date().toISOString().slice(0,10);const d=new Date(String(raw).includes('T')?raw:raw+'T00:00:00Z');return isNaN(d)?new Date():d;}
function mmYearsAfter(d,y){const x=new Date(+d);x.setUTCFullYear(x.getUTCFullYear()+y);return x;}
function mmIsoDate(d){return new Date(d).toISOString().slice(0,10);}
function mmWindowDates(x){return [new Date(String(x.start).includes('T')?x.start:x.start+'T00:00:00Z'),new Date(String(x.end).includes('T')?x.end:x.end+'T00:00:00Z')];}
function mmDashaTimeline(c,start,end){const out=[];for(const md of dashaPeriods(c)){const [ms,me]=mmWindowDates(md);if(me<start||ms>end)continue;const ml=mmCanonPlanet(md.lord||md.name);out.push({level:'MD',lord:ml,parent:null,start:md.start,end:md.end,label:`${mmPlanetText(ml)} ${T('Mahadasha','மகாதசை')}`});for(const ad of (md.antardashas||md.bhuktis||md.subPeriods||[])){const [as,ae]=mmWindowDates(ad);if(ae<start||as>end)continue;const al=mmCanonPlanet(ad.lord||ad.name);out.push({level:'AD',lord:al,parent:ml,start:ad.start,end:ad.end,label:`${mmPlanetText(ml)}/${mmPlanetText(al)} ${T('Bhukti','புக்தி')}`});}}return out;}
