const MM_PLANET_LABEL={
 [P.Sun]:['Sun','சூரியன்'],[P.Moon]:['Moon','சந்திரன்'],[P.Mars]:['Mars','செவ்வாய்'],[P.Mercury]:['Mercury','புதன்'],[P.Jupiter]:['Jupiter','குரு'],[P.Venus]:['Venus','சுக்கிரன்'],[P.Saturn]:['Saturn','சனி'],[P.Rahu]:['Rahu','ராகு'],[P.Ketu]:['Ketu','கேது']
};
const MM_SOFT=new Set([P.Jupiter,P.Venus,P.Mercury,P.Moon]);
const MM_FIRM=new Set([P.Mars,P.Saturn,P.Rahu,P.Ketu]);
function mmHumanPlanetLabel(name){const x=MM_PLANET_LABEL[name]||[String(name),String(name)];return T(x[0],x[1]);}
function mmHumanLayer(c,n=1){const raw=n===1?c:mmDivision(c,n);if(!raw)return null;let lag=Number(raw?.lagna?.longitude??raw?.ascendant?.longitude);if(!Number.isFinite(lag)&&n===9){const r=c?.navamsa?.lagna?.rasi;let idx=SIGNS_TA.indexOf(r);if(idx<0)idx=SIGNS_EN.indexOf(r);if(idx>=0)lag=idx*30;}const planets=Array.isArray(raw?.planets)?raw.planets.map(p=>({...p,name:p.name||p.planet})):[];if(!Number.isFinite(lag)||!planets.length)return null;return {n,raw,lag,planets};}
function mmHumanPlanet(layer,name){return layer?.planets?.find(p=>mmPlanetMatches(p?.name,name))||null;}
function mmHumanHouseLord(layer,h){if(!layer)return null;return LORD[(si(layer.lag)+(Number(h)-1)+12)%12];}
function mmHumanPlanetHouse(layer,name){const p=mmHumanPlanet(layer,name);return p?house(p.longitude,layer.lag):null;}
function mmHumanDignityDelta(name,lon){if(!Number.isFinite(Number(lon)))return 0;const s=si(lon);if(EXALT[name]===s)return 2;if((OWN[name]||[]).includes(s))return 1.5;if(DEBIL[name]===s)return -2;return 0;}
function mmHumanPlacementDelta(h){if([1,4,5,7,9,10,11].includes(h))return .6;if([6,8,12].includes(h))return -.45;return 0;}
function mmHumanAspectDelta(name){if(name===P.Jupiter)return 1.1;if(name===P.Venus)return .7;if(name===P.Mercury||name===P.Moon)return .45;if(name===P.Saturn)return -.75;if(name===P.Mars)return -.65;if(name===P.Rahu||name===P.Ketu)return -.55;return 0;}
function mmHumanLayerTopic(layer,topic,weight=1){
 if(!layer)return {score:0,evidence:[]};let score=0;const evidence=[];
 const houses=topic.houses||[];
 for(const h of houses){
  const lord=mmHumanHouseLord(layer,h),lp=mmHumanPlanet(layer,lord);
  if(lp){const lh=house(lp.longitude,layer.lag),d=mmHumanDignityDelta(lord,lp.longitude);score+=(d+mmHumanPlacementDelta(lh))*weight;evidence.push(`${layer.n===1?'D1':'D9'} ${T('house','பாவம்')} ${h} ${T('lord','அதிபதி')} ${mmHumanPlanetLabel(lord)} — ${sign(si(lp.longitude))}, ${T('house','பாவம்')} ${lh}, ${dignity(lord,lp.longitude)}`);}
  const occupants=layer.planets.filter(p=>house(p.longitude,layer.lag)===h);
  for(const p of occupants){const name=Object.keys(MM_PLANET_LABEL).find(k=>mmPlanetMatches(p?.name,k));if(!name)continue;score+=(MM_SOFT.has(name)?.4:MM_FIRM.has(name)?-.35:0)*weight;evidence.push(`${layer.n===1?'D1':'D9'} ${T('house','பாவம்')} ${h}: ${mmHumanPlanetLabel(name)} ${T('occupies','இருக்கிறது')}`);}
  const target={longitude:((si(layer.lag)+h-1)%12)*30+15};
  for(const name of Object.keys(MM_PLANET_LABEL)){const p=mmHumanPlanet(layer,name);if(!p)continue;const a=aspectProfile(name,p,target);if(a.exists){score+=mmHumanAspectDelta(name)*weight;evidence.push(`${layer.n===1?'D1':'D9'} ${mmHumanPlanetLabel(name)} → ${T('house','பாவம்')} ${h} ${T('aspect','பார்வை')}`);}}
 }
 for(const name of topic.planets||[]){const p=mmHumanPlanet(layer,name);if(!p)continue;const ph=house(p.longitude,layer.lag),d=mmHumanDignityDelta(name,p.longitude);score+=(d*.65+((houses.includes(ph))?.55:0)+mmHumanPlacementDelta(ph)*.35)*weight;evidence.push(`${layer.n===1?'D1':'D9'} ${mmHumanPlanetLabel(name)} — ${sign(si(p.longitude))}, ${T('house','பாவம்')} ${ph}, ${dignity(name,p.longitude)}`);for(const other of Object.keys(MM_PLANET_LABEL)){if(other===name)continue;const op=mmHumanPlanet(layer,other),cj=conjunctionProfile(p,op);if(cj.sameSign&&cj.separation<=8){score+=(MM_SOFT.has(other)?.35:MM_FIRM.has(other)?-.3:0)*weight;evidence.push(`${layer.n===1?'D1':'D9'} ${mmHumanPlanetLabel(name)} + ${mmHumanPlanetLabel(other)} ${T('close conjunction','நெருக்கமான சேர்க்கை')}`);}}
 }
 return {score,evidence};
}
function mmHumanTopicProfile(c,topic){const d1=mmHumanLayer(c,1),d9=mmHumanLayer(c,9);const a=mmHumanLayerTopic(d1,topic,1),b=mmHumanLayerTopic(d9,topic,.72);return {score:a.score+b.score,evidence:[...a.evidence,...b.evidence].slice(0,8),d1,d9};}
function mmHumanElementStyle(c,topic){
 const d1=mmHumanLayer(c,1);if(!d1)return T('the available D1 factors show a mixed style','கிடைக்கும் D1 காரணிகள் கலப்பு அணுகுமுறையை காட்டுகின்றன');
 let p=null;if(topic.anchor)p=mmHumanPlanet(d1,topic.anchor);
 const idx=p?si(p.longitude):si(d1.lag),sgn=sign(idx),sty=MM_SIGN_STYLE[idx]||MM_SIGN_STYLE[0],base=T(sty.en,sty.ta),anchor=topic.anchor?mmHumanPlanetLabel(topic.anchor):T('Lagna','லக்னம்');
 return lang()==='ta'?`${anchor} ${sgn} ராசியில் இருப்பதால் ${base}`:`${anchor} in ${sgn} shows a ${base} approach`;
}
function mmHumanBand(score){return score>=2.25?'good':score<=-1.5?'care':'mixed';}
const MM_HUMAN_TOPICS=[
 {en:'Temperament and basic nature',ta:'குணநிலை மற்றும் அடிப்படை இயல்பு',houses:[1],planets:[P.Sun,P.Moon],anchor:P.Sun,good:['Both can recognise each other’s basic nature without needing constant correction.','ஒருவரின் அடிப்படை குணத்தை மற்றவர் எளிதாகப் புரிந்து கொண்டு ஏற்றுக்கொள்ளும் வாய்ப்பு அதிகம்.'],care:['Their natural pace and self-expression can differ; giving each other room before reacting will matter.','இருவரின் இயல்பான வேகம் மற்றும் சுய வெளிப்பாடு மாறுபடலாம்; உடனடி எதிர்வினைக்கு பதில் ஒருவருக்கொருவர் இடம் கொடுப்பது நல்லது.']},
 {en:'Mind and emotional response',ta:'மனம் மற்றும் உணர்ச்சி வெளிப்பாடு',houses:[1,4],planets:[P.Moon],anchor:P.Moon,good:['Emotional needs are easier to understand and respond to with care.','உணர்ச்சி தேவைகளை ஒருவருக்கொருவர் புரிந்து கொண்டு அக்கறையுடன் பதிலளிக்கும் திறன் நல்லதாக இருக்கலாம்.'],care:['One may need words while the other needs silence or time; this difference should not be mistaken for lack of affection.','ஒருவருக்கு பேசுவது தேவைப்படும்போது மற்றவருக்கு அமைதி அல்லது நேரம் தேவைப்படலாம்; இதை அன்பின்மை என்று தவறாக எடுத்துக்கொள்ளக் கூடாது.']},
 {en:'Speech and communication',ta:'பேச்சு மற்றும் தொடர்பு முறை',houses:[2,3],planets:[P.Mercury],anchor:P.Mercury,good:['Discussion, explanation and problem-solving can become a strength of the relationship.','பேச்சு, விளக்கம் மற்றும் பிரச்சினையை சேர்ந்து தீர்ப்பது உறவின் வலுவான அம்சமாக மாறலாம்.'],care:['Tone, timing and assumptions can create unnecessary misunderstandings; important matters should be stated clearly.','பேச்சின் தொனி, நேரம் மற்றும் முன் ஊகங்கள் தேவையற்ற தவறான புரிதலை உருவாக்கலாம்; முக்கிய விஷயங்களை தெளிவாகச் சொல்லுவது அவசியம்.']},
 {en:'Affection and love language',ta:'அன்பை வெளிப்படுத்தும் முறை',houses:[5,7],planets:[P.Venus,P.Moon],anchor:P.Venus,good:['Affection can be shown in ways that the other person can recognise and value.','அன்பை வெளிப்படுத்தும் முறை மற்றவரால் புரிந்து கொள்ளப்பட்டு மதிக்கப்படும் வாய்ப்பு உள்ளது.'],care:['They may express love differently—through words, practical help, time or closeness—so expectations should be spoken rather than assumed.','அன்பை ஒருவர் வார்த்தையால், மற்றவர் செயல், நேரம் அல்லது நெருக்கம் மூலம் காட்டக்கூடும்; எதிர்பார்ப்புகளை ஊகிக்காமல் பேசிக் கொள்ள வேண்டும்.']},
 {en:'Marriage expectations',ta:'திருமண எதிர்பார்ப்பு',houses:[7],planets:[P.Venus,P.Jupiter],anchor:P.Venus,good:['Expectations about companionship, respect and shared life can be brought onto common ground.','துணைமை, மரியாதை மற்றும் கூட்டு வாழ்க்கை குறித்த எதிர்பார்ப்புகளை ஒரே பாதைக்கு கொண்டு வர முடியும்.'],care:['Unspoken expectations about spouse roles can become a source of disappointment; roles should be discussed before major commitments.','துணைவர் எப்படி இருக்க வேண்டும் என்ற சொல்லப்படாத எதிர்பார்ப்புகள் ஏமாற்றத்தை உருவாக்கலாம்; பெரிய முடிவுகளுக்கு முன் பொறுப்புகளைப் பேசிக் கொள்ள வேண்டும்.']},
 {en:'Intimacy and private life',ta:'தாம்பத்ய நெருக்கம் மற்றும் தனியுரிமை',houses:[7,8,12],planets:[P.Venus,P.Mars],anchor:P.Venus,good:['Trust, consent and private closeness can deepen gradually when both feel respected.','மரியாதை மற்றும் சம்மதம் நிலைத்திருந்தால் தாம்பத்ய நெருக்கமும் நம்பிக்கையும் காலத்தோடு ஆழமாகலாம்.'],care:['Privacy, closeness and personal boundaries may need deliberate communication rather than assumption.','தனியுரிமை, நெருக்கம் மற்றும் தனிப்பட்ட எல்லைகள் குறித்து ஊகிப்பதை விட வெளிப்படையாகப் பேசுவது நல்லது.']},
 {en:'Home atmosphere and residence',ta:'வீட்டு சூழல் மற்றும் வசிப்பு முறை',houses:[4,7,12],planets:[P.Moon,P.Venus],anchor:P.Moon,good:['They can create a home rhythm that gives both comfort and belonging.','இருவருக்கும் நிம்மதி மற்றும் சொந்தத்தன்மை தரும் வீட்டுச் சூழலை உருவாக்கும் வாய்ப்பு உள்ளது.'],care:['Differences in privacy, cleanliness, routine or residence preference should be settled practically.','தனியுரிமை, சுத்தம், தினசரி ஒழுங்கு அல்லது வசிக்கும் இடம் பற்றிய வேறுபாடுகளை நடைமுறையாகத் தீர்மானிக்க வேண்டும்.']},
 {en:'Family background and relatives',ta:'குடும்ப பின்னணி மற்றும் உறவினர்கள்',houses:[2,4,9],planets:[P.Moon,P.Jupiter],anchor:P.Jupiter,good:['Both families can be integrated with clearer boundaries and mutual respect.','தெளிவான எல்லைகளும் பரஸ்பர மரியாதையும் இருந்தால் இரு குடும்பங்களையும் நல்ல முறையில் இணைக்க முடியும்.'],care:['Family customs or relatives’ involvement may differ; the couple should decide together where boundaries are needed.','குடும்ப வழக்கங்கள் அல்லது உறவினர்களின் தலையீடு மாறுபடலாம்; எங்கு எல்லை தேவை என்பதை இருவரும் சேர்ந்து தீர்மானிக்க வேண்டும்.']},
 {en:'Money, savings and spending',ta:'பணம், சேமிப்பு மற்றும் செலவு',houses:[2,11,12],planets:[P.Jupiter,P.Venus,P.Mercury],anchor:P.Jupiter,good:['A shared budget and long-term saving plan can work well when decisions are transparent.','வரவு-செலவு வெளிப்படையாக இருந்தால் கூட்டு பட்ஜெட் மற்றும் நீண்டகால சேமிப்பு திட்டம் நன்றாக இயங்கலாம்.'],care:['One may prioritise security while the other prioritises comfort or opportunity; joint rules for major spending will help.','ஒருவர் பாதுகாப்பை முன்னிலைப்படுத்த, மற்றவர் வசதி அல்லது வாய்ப்பை முன்னிலைப்படுத்தலாம்; பெரிய செலவுகளுக்கு கூட்டு விதிகள் உதவும்.']},
 {en:'Career and mutual support',ta:'தொழில் மற்றும் ஒருவருக்கொருவர் ஆதரவு',houses:[6,10,11],planets:[P.Sun,P.Saturn,P.Mercury],anchor:P.Saturn,good:['Each person can support the other’s work goals without turning career into competition.','தொழிலை போட்டியாக மாற்றாமல் ஒருவரின் வளர்ச்சியை மற்றவர் ஆதரிக்கும் சூழல் உருவாகலாம்.'],care:['Work hours, transfers or ambition can reduce shared time; career decisions should include their effect on family life.','வேலை நேரம், இடமாற்றம் அல்லது உயர்வு நோக்கம் கூட்டு நேரத்தை குறைக்கலாம்; தொழில் முடிவுகளில் குடும்ப விளைவையும் சேர்த்து பார்க்க வேண்டும்.']},
 {en:'Sharing responsibilities',ta:'பொறுப்புகளைப் பகிரும் முறை',houses:[4,6,10],planets:[P.Saturn,P.Sun],anchor:P.Saturn,good:['Responsibilities can be divided according to ability rather than gender or habit.','பழக்கம் அல்லது பாலினத்தை விட திறமை மற்றும் நேரத்தைப் பொறுத்து பொறுப்புகளைப் பகிர முடியும்.'],care:['If one person silently carries more duties, resentment can build; responsibilities should be reviewed openly.','ஒருவர் மட்டும் அமைதியாக அதிக பொறுப்பு ஏற்றால் மனக்கசப்பு உருவாகலாம்; பொறுப்புகளை காலம்தோறும் பேசிப் பகிர வேண்டும்.']},
 {en:'Decision-making style',ta:'முடிவு எடுக்கும் முறை',houses:[1,3,9],planets:[P.Sun,P.Mercury,P.Jupiter],anchor:P.Mercury,good:['Major choices can improve when one brings ideas and the other brings judgement or practicality.','ஒருவர் புதிய யோசனையையும் மற்றவர் தீர்மானம் அல்லது நடைமுறையையும் கொண்டு வந்தால் பெரிய முடிவுகள் மேம்படலாம்.'],care:['Fast decisions versus careful decisions can clash; set a time limit for discussion and then decide together.','விரைவான முடிவு மற்றும் நீண்ட சிந்தனை மோதலாம்; பேசுவதற்கான நேரத்தை நிர்ணயித்து பின்னர் சேர்ந்து முடிவு எடுப்பது நல்லது.']},
 {en:'Anger and disagreement',ta:'கோபம் மற்றும் கருத்து வேறுபாடு',houses:[3,6,7,8],planets:[P.Mars,P.Saturn],anchor:P.Mars,good:['Differences can be handled directly without carrying them for long when both follow fair rules.','நியாயமான விதிகளைப் பின்பற்றினால் கருத்து வேறுபாட்டை நீண்ட நாட்கள் சுமக்காமல் நேரடியாகத் தீர்க்க முடியும்.'],care:['Sharp words, silence or stubbornness can worsen a small issue; do not make financial or relationship decisions in anger.','கடுமையான வார்த்தை, பேசாமல் இருப்பது அல்லது பிடிவாதம் சிறிய விஷயத்தை பெரிதாக்கலாம்; கோபத்தில் பணம் அல்லது உறவு முடிவுகளை எடுக்க வேண்டாம்.']},
 {en:'Reconciliation and forgiveness',ta:'சமரசம் மற்றும் மீண்டும் இணையும் திறன்',houses:[4,7,9],planets:[P.Moon,P.Venus,P.Jupiter],anchor:P.Jupiter,good:['The relationship has room to repair after disagreement when both are willing to explain and listen.','கருத்து வேறுபாட்டிற்குப் பிறகு இருவரும் விளக்கி கேட்கத் தயாராக இருந்தால் உறவை மீண்டும் சீர்செய்யும் திறன் உள்ளது.'],care:['Old issues should not be repeatedly reopened; agree on what is resolved and what still needs action.','முடிந்த பழைய பிரச்சினைகளை மீண்டும் மீண்டும் திறக்காமல், எது தீர்ந்தது எதற்கு இன்னும் செயல் தேவை என்பதைத் தெளிவுபடுத்த வேண்டும்.']},
 {en:'Trust and transparency',ta:'நம்பிக்கை மற்றும் வெளிப்படைத்தன்மை',houses:[2,7,8],planets:[P.Sun,P.Jupiter,P.Rahu,P.Ketu],anchor:P.Jupiter,good:['Trust grows when money, plans and personal boundaries are discussed honestly.','பணம், திட்டங்கள் மற்றும் தனிப்பட்ட எல்லைகள் குறித்து நேர்மையாகப் பேசும்போது நம்பிக்கை வலுப்படும்.'],care:['Secrecy or half-information can be more damaging than the issue itself; difficult topics should be discussed early.','மறைவு அல்லது முழுமையற்ற தகவல் பிரச்சினையை விட அதிக பாதிப்பை ஏற்படுத்தலாம்; கடினமான விஷயங்களை ஆரம்பத்திலேயே பேசுவது நல்லது.']},
 {en:'Independence and personal space',ta:'சுயநிலை மற்றும் தனிப்பட்ட இடம்',houses:[1,12],planets:[P.Saturn,P.Ketu,P.Moon],anchor:P.Saturn,good:['Personal space can coexist with closeness when both respect each other’s routines and friendships.','தனிநேரம், நண்பர்கள் மற்றும் பழக்கங்களை மரியாதை செய்தால் நெருக்கத்துடன் சுயநிலையும் இணைந்து இருக்கலாம்.'],care:['One may interpret distance as rejection while the other sees it as normal personal space; this difference should be named clearly.','ஒருவர் இடைவெளியை அன்பின்மை என்று நினைக்க, மற்றவர் அதை இயல்பான தனிநேரம் என்று பார்க்கலாம்; இந்த வேறுபாட்டை தெளிவாகப் பேச வேண்டும்.']},
 {en:'Friends and social life',ta:'நண்பர்கள் மற்றும் சமூக வாழ்க்கை',houses:[3,7,11],planets:[P.Mercury,P.Venus,P.Rahu],anchor:P.Mercury,good:['Social circles can broaden the relationship without weakening couple time.','நண்பர்கள் மற்றும் சமூக வட்டம் தம்பதியரின் நேரத்தை குறைக்காமல் உறவுக்கு புதிய அனுபவங்களை தரலாம்.'],care:['Different social needs may create friction; agree on couple time, family time and friend time.','சமூக தொடர்பு தேவைகள் மாறுபடலாம்; தம்பதியர் நேரம், குடும்ப நேரம் மற்றும் நண்பர்கள் நேரம் ஆகியவற்றை சமநிலைப்படுத்த வேண்டும்.']},
 {en:'Children and parenting approach',ta:'குழந்தைகள் மற்றும் பெற்றோர் அணுகுமுறை',houses:[5,9],planets:[P.Jupiter,P.Moon],anchor:P.Jupiter,good:['Values around care, learning and discipline can be aligned through discussion.','அன்பு, கல்வி மற்றும் ஒழுக்கம் குறித்து பேசிக் கொண்டால் குழந்தை வளர்ப்பு மதிப்புகளை ஒரே பாதைக்கு கொண்டு வரலாம்.'],care:['Differences in discipline or expectations for children should be agreed before they become repeated arguments.','குழந்தைகளின் ஒழுக்கம் அல்லது எதிர்பார்ப்பில் வேறுபாடு இருந்தால் அது தொடர்ச்சியான வாதமாக மாறுவதற்கு முன் ஒப்புதல் தேவை.']},
 {en:'Learning and intellectual companionship',ta:'கல்வி, அறிவு மற்றும் சிந்தனைப் பகிர்வு',houses:[4,5,9],planets:[P.Mercury,P.Jupiter],anchor:P.Mercury,good:['Learning, discussion and shared interests can keep the relationship mentally active.','கற்றல், விவாதம் மற்றும் பொதுவான ஆர்வங்கள் உறவை மனதளவில் உயிர்ப்புடன் வைத்திருக்கலாம்.'],care:['Different opinions need not become personal criticism; debate should remain respectful.','வேறு கருத்துகள் தனிப்பட்ட விமர்சனமாக மாற வேண்டியதில்லை; விவாதத்தில் மரியாதை நிலைத்திருக்க வேண்டும்.']},
 {en:'Values, faith and meaning',ta:'வாழ்க்கை மதிப்புகள், நம்பிக்கை மற்றும் ஆன்மீகம்',houses:[9,12],planets:[P.Jupiter,P.Ketu],anchor:P.Jupiter,good:['Shared values can become a stable reference point during difficult decisions.','கடினமான முடிவுகளில் பொதுவான வாழ்க்கை மதிப்புகள் உறவுக்கு நிலையான வழிகாட்டியாக இருக்கலாம்.'],care:['Religious practice or personal philosophy may differ; respect is more important than forcing uniformity.','வழிபாட்டு முறை அல்லது தனிப்பட்ட தத்துவம் மாறுபடலாம்; ஒரே மாதிரி இருக்க வேண்டும் என்று வற்புறுத்துவதை விட மரியாதை முக்கியம்.']},
 {en:'Travel and relocation',ta:'பயணம் மற்றும் இடமாற்றம்',houses:[3,9,12],planets:[P.Moon,P.Rahu],anchor:P.Rahu,good:['Travel or relocation can be managed as a joint project when practical needs are planned first.','பயணம் அல்லது இடமாற்றத்தை நடைமுறை தேவைகளை முன்கூட்டியே திட்டமிட்டு கூட்டு முடிவாக மேற்கொள்ளலாம்.'],care:['One may welcome change more easily than the other; work, parents, children and finances should be considered before relocation.','ஒருவர் மாற்றத்தை எளிதாக ஏற்க, மற்றவர் தயங்கலாம்; இடமாற்றத்திற்கு முன் வேலை, பெற்றோர், குழந்தைகள் மற்றும் பணநிலையை சேர்த்து பார்க்க வேண்டும்.']},
 {en:'Daily routine and lifestyle',ta:'தினசரி ஒழுங்கு மற்றும் வாழ்க்கை நடை',houses:[1,6],planets:[P.Moon,P.Saturn],anchor:P.Moon,good:['Daily routines can become predictable enough to reduce unnecessary friction.','தினசரி ஒழுங்கு தெளிவாக இருந்தால் தேவையற்ற கருத்து வேறுபாடுகள் குறையலாம்.'],care:['Sleep, food, work timing or household habits may differ; practical routines work better than criticism.','உறக்கம், உணவு, வேலை நேரம் அல்லது வீட்டு பழக்கங்கள் மாறுபடலாம்; விமர்சனத்தை விட நடைமுறை ஒழுங்கு அமைத்தல் உதவும்.']},
 {en:'Shared assets, debt and property',ta:'கூட்டு சொத்து, கடன் மற்றும் நிதிப் பொறுப்பு',houses:[2,4,8,11],planets:[P.Jupiter,P.Saturn,P.Venus],anchor:P.Saturn,good:['Property and long-term commitments can be handled better with documentation and joint planning.','சொத்து மற்றும் நீண்டகால நிதிப் பொறுப்புகளை ஆவணத்துடனும் கூட்டு திட்டத்துடனும் கையாளலாம்.'],care:['Debt, guarantees or family property should never rely on verbal assumptions alone; document major commitments.','கடன், உத்தரவாதம் அல்லது குடும்பச் சொத்து விஷயங்களில் வாய்வழி ஊகத்தை மட்டும் நம்பாமல் முக்கிய முடிவுகளை ஆவணப்படுத்த வேண்டும்.']},
 {en:'Long-term marital stability',ta:'நீண்டகால திருமண நிலைத்தன்மை',houses:[2,7,8,11],planets:[P.Saturn,P.Jupiter,P.Venus],anchor:P.Saturn,good:['Stability is more likely to grow through reliability, shared responsibilities and repeated small acts of trust.','நம்பகத்தன்மை, பகிரப்பட்ட பொறுப்பு மற்றும் தொடர்ந்து செய்யப்படும் சிறிய நல்ல செயல்கள் மூலம் உறவு நிலைத்தன்மை வளரலாம்.'],care:['Long-term stability will depend less on one favourable factor and more on how both manage repeated practical issues.','ஒரே ஒரு நல்ல காரணியை விட தினசரி மீண்டும் வரும் நடைமுறை விஷயங்களை இருவரும் எப்படி கையாள்கிறார்கள் என்பதே நீண்டகால நிலைத்தன்மைக்கு முக்கியம்.']},
 {en:'How the relationship matures with time (D9)',ta:'காலத்தோடு உறவு முதிரும் விதம் (D9)',houses:[1,7,9],planets:[P.Venus,P.Jupiter,P.Saturn],anchor:P.Venus,good:['D9 supports the possibility that the relationship becomes more mature as shared experience grows.','D9 அடிப்படையில் கூட்டு அனுபவம் அதிகரிக்கும்போது உறவு முதிர்ச்சியடையும் வாய்ப்பு உள்ளது.'],care:['D9 suggests that maturity may come through learning boundaries, responsibility and realistic expectations rather than effortless harmony.','D9 அடிப்படையில் எளிதான ஒற்றுமையை விட எல்லைகள், பொறுப்பு மற்றும் நடைமுறை எதிர்பார்ப்புகளை கற்றுக் கொள்வதன் மூலம் உறவு முதிரலாம்.']}
];
function mmHumanCoupleText(topic,B,G){return mm239PairBalance(topic,B,G);}

const MM_HUMAN_GUIDANCE=[
 ['When differences appear, avoid trying to correct personality itself; agree instead on how decisions, time and responsibilities will be handled.','வேறுபாடு தெரியும் போது ஒருவரின் குணத்தை மாற்ற முயலாமல், முடிவு எடுக்கும் முறை, நேரம் மற்றும் பொறுப்புகளை எப்படிப் பகிர்வது என்பதை முன்கூட்டியே ஒப்புக்கொள்வது நல்லது.'],
 ['During emotionally heavy days, ask what the other person needs before giving advice; reassurance, silence and conversation do not work equally for everyone.','உணர்ச்சி அதிகமான நேரங்களில் உடனே அறிவுரை கூறாமல், மற்றவருக்கு என்ன தேவை என்று கேட்பது நல்லது; ஆறுதல், அமைதி, உரையாடல் ஆகியவை எல்லோருக்கும் ஒரே விதமாகச் செயல்படாது.'],
 ['Important subjects should be discussed when both are calm; short messages, assumptions or third-party communication can magnify avoidable misunderstanding.','முக்கிய விஷயங்களை இருவரும் அமைதியாக இருக்கும் போது பேசுவது நல்லது; குறுகிய செய்தி, முன் ஊகம் அல்லது மூன்றாம் நபர் மூலம் பேசுதல் தேவையற்ற தவறான புரிதலை பெரிதாக்கலாம்.'],
 ['Each should learn how the other recognises affection—words, time, practical help or physical closeness—rather than measuring love only by one preferred style.','அன்பை ஒருவர் வார்த்தை, மற்றவர் நேரம், செயல் உதவி அல்லது நெருக்கம் மூலம் உணரக்கூடும்; ஒரே ஒரு வெளிப்பாட்டு முறையையே அன்பின் அளவாகக் கருதாமல் ஒருவரின் முறையை மற்றவர் புரிந்து கொள்ள வேண்டும்.'],
 ['Before marriage, expectations about work, money, parents, residence and privacy should be spoken plainly; unspoken role expectations become repeated friction later.','திருமணத்திற்கு முன் வேலை, பணம், பெற்றோர், வசிப்பிடம் மற்றும் தனியுரிமை பற்றிய எதிர்பார்ப்புகளை தெளிவாகப் பேச வேண்டும்; சொல்லப்படாத பொறுப்பு எதிர்பார்ப்புகள் பின்னர் மீண்டும் வரும் மனக்கசப்பாக மாறலாம்.'],
 ['Private closeness improves with emotional safety, consent, time and trust; pressure or comparison usually weakens rather than improves intimacy.','தாம்பத்ய நெருக்கம் உணர்ச்சி பாதுகாப்பு, சம்மதம், நேரம் மற்றும் நம்பிக்கையால் வளர்கிறது; அழுத்தம் அல்லது ஒப்பீடு நெருக்கத்தை மேம்படுத்தாமல் குறைக்கக்கூடும்.'],
 ['A peaceful home depends less on decoration and more on routine, privacy, noise, visitors and shared domestic responsibilities being mutually acceptable.','வீட்டு அமைதி அலங்காரத்தை விட தினசரி ஒழுங்கு, தனியுரிமை, சத்தம், விருந்தினர் வருகை மற்றும் வீட்டு பொறுப்பு இருவருக்கும் ஏற்றவாறு அமைந்துள்ளதா என்பதில் அதிகம் சாரும்.'],
 ['Family boundaries should be agreed as a couple first. Respecting both families does not require allowing every relative to participate in private decisions.','குடும்ப எல்லைகளை முதலில் தம்பதிகள் இருவரும் ஒப்புக்கொள்ள வேண்டும். இரு குடும்பங்களையும் மதிப்பது என்பது தனிப்பட்ட முடிவுகளில் எல்லா உறவினர்களையும் சேர்க்க வேண்டும் என்பதல்ல.'],
 ['A shared budget works best when income, fixed commitments, personal spending and savings goals are visible to both partners.','வருமானம், நிலையான செலவுகள், தனிப்பட்ட செலவு மற்றும் சேமிப்பு இலக்கு இருவருக்கும் தெளிவாக இருந்தால் கூட்டு பணநிர்வாகம் சிறப்பாக இயங்கும்.'],
 ['Career support means allowing each person’s ambition to exist without turning success into comparison; major job decisions should be discussed for their effect on the household.','ஒருவரின் முன்னேற்றத்தை மற்றவருடன் ஒப்பிடாமல் இருவரின் தொழில் இலக்கையும் மதிப்பதே உண்மையான ஆதரவு; பெரிய வேலை முடிவுகள் குடும்பத்தின் மீது ஏற்படும் தாக்கத்துடன் சேர்த்து பேசப்பட வேண்டும்.'],
 ['Responsibilities should be divided by time, capacity and skill rather than by silent habit. Rebalancing is normal when work or family demands change.','பொறுப்புகளை பழக்கப்படி அமைதியாக ஏற்றுக்கொள்ளாமல், நேரம், திறன் மற்றும் வசதிக்கு ஏற்ப பகிர வேண்டும்; வேலை அல்லது குடும்ப நிலை மாறும்போது மீண்டும் பகிர்வது இயல்பானது.'],
 ['For major decisions, separate the emotional reaction from the practical decision. A short pause can prevent one person’s speed from overpowering the other’s caution.','பெரிய முடிவுகளில் உணர்ச்சி எதிர்வினையையும் நடைமுறை முடிவையும் பிரித்துப் பார்க்க வேண்டும்; சிறிய இடைவெளி ஒருவரின் வேகம் மற்றவரின் எச்சரிக்கையை அழுத்தாமல் காக்கும்.'],
 ['Arguments should focus on the present issue, not old mistakes or character attacks. A clear pause-and-return rule can protect the relationship during heated moments.','வாக்குவாதத்தில் தற்போதைய விஷயத்தை மட்டும் பேசுவது நல்லது; பழைய தவறு அல்லது குணநலன் குற்றச்சாட்டை சேர்க்காமல், கோபம் அதிகரித்தால் சிறிது இடைவெளி எடுத்துப் பின்னர் பேசும் ஒப்பந்தம் உதவும்.'],
 ['Repair matters more than never arguing. A sincere apology should identify the specific hurt, acknowledge responsibility and change the repeated behaviour.','எப்போதும் சண்டை இல்லாமல் இருப்பதை விட, சண்டைக்குப் பிறகு உறவை சரிசெய்யும் திறன் முக்கியம்; மன்னிப்பு கூறும்போது எந்த செயல் காயப்படுத்தியது என்பதை ஏற்று, மீண்டும் நடக்காத மாற்றமும் இருக்க வேண்டும்.'],
 ['Trust grows from consistency: money, communication, plans and boundaries should match what was previously agreed. Repeated small inconsistencies matter more than one grand promise.','நம்பிக்கை தொடர்ச்சியான நடத்தை மூலம் வளர்கிறது; பணம், தொடர்பு, திட்டம் மற்றும் எல்லைகள் முன்பு ஒப்புக்கொண்டதுடன் பொருந்த வேண்டும். ஒரு பெரிய வாக்குறுதியை விட மீண்டும் வரும் சிறிய முரண்பாடுகள் அதிக தாக்கம் தரலாம்.'],
 ['Personal space should be discussed, not guessed. Time alone, friendships and hobbies can coexist with commitment when expectations are transparent.','தனிப்பட்ட இடத்தை ஊகிக்காமல் பேசிக் கொள்ள வேண்டும். தனிநேரம், நண்பர்கள் மற்றும் விருப்பங்கள் பற்றிய எதிர்பார்ப்பு தெளிவாக இருந்தால் அவை உறவின் பற்றுதலுடன் இணைந்து இயங்க முடியும்.'],
 ['Friends should support the relationship rather than become a substitute for couple communication. Sensitive matters are better discussed between partners before being shared widely.','நண்பர்கள் உறவுக்கு ஆதரவாக இருக்க வேண்டும்; தம்பதிகளுக்கிடையிலான உரையாடலை மாற்றக்கூடாது. நுணுக்கமான விஷயங்களை வெளியில் பகிர்வதற்கு முன் இருவரும் பேசிக் கொள்வது நல்லது.'],
 ['Parenting works better when both agree on discipline, education, money and family involvement before conflicts arise. Children should not be used as messengers during couple disagreements.','குழந்தை வளர்ப்பில் ஒழுக்கம், கல்வி, பணச் செலவு மற்றும் குடும்ப உறுப்பினர்களின் பங்கு குறித்து முன்கூட்டியே ஒத்த கருத்து வைத்தால் சிக்கல்கள் குறையும்; தம்பதிகள் கருத்து வேறுபாட்டில் குழந்தைகளை நடுவர் அல்லது செய்தியாளர் ஆக்கக்கூடாது.'],
 ['Shared learning, discussion and curiosity can keep the relationship mentally alive. Differences in education level matter less than mutual respect for each other’s thinking.','கூட்டு கற்றல், உரையாடல் மற்றும் ஆர்வம் உறவை மனதளவில் உயிருடன் வைத்திருக்க உதவும்; கல்வித் தகுதி வேறுபாட்டை விட ஒருவரின் சிந்தனையை மற்றவர் மதிப்பது முக்கியம்.'],
 ['Faith or personal philosophy should provide meaning, not become a tool to control the other person. Shared practice can be valuable, but respectful difference is also workable.','நம்பிக்கை அல்லது ஆன்மீகம் வாழ்க்கைக்கு அர்த்தம் தர வேண்டும்; மற்றவரை கட்டுப்படுத்தும் கருவியாக மாறக்கூடாது. கூட்டு வழிபாடு நல்லதாக இருந்தாலும் மரியாதையான வேறுபாடும் ஏற்றுக்கொள்ளப்பட வேண்டும்.'],
 ['Before relocation, compare work, housing, parents, children, finances and support networks. One partner’s opportunity should not silently become the other partner’s loss.','இடமாற்றத்திற்கு முன் வேலை, வீடு, பெற்றோர், குழந்தைகள், பணநிலை மற்றும் ஆதரவு வலையமைப்பை சேர்த்து பார்க்க வேண்டும்; ஒருவரின் வாய்ப்பு மற்றவரின் இழப்பாக அமைதியாக மாறக்கூடாது.'],
 ['Small routines often decide marital comfort more than major promises. Sleep, food, chores, screen time and weekly planning deserve practical agreement.','பெரிய வாக்குறுதிகளை விட தினசரி சிறிய ஒழுங்குகள் திருமண நிம்மதியை அதிகம் தீர்மானிக்கலாம்; உறக்கம், உணவு, வீட்டு வேலை, மொபைல் நேரம் மற்றும் வார திட்டத்தில் நடைமுறை ஒப்புதல் உதவும்.'],
 ['Loans, guarantees, property and family money should be documented clearly. Both should know the liability before signing or committing.','கடன், உத்தரவாதம், சொத்து மற்றும் குடும்பப் பண விஷயங்களை ஆவணப்படுத்த வேண்டும்; கையெழுத்து அல்லது பெரிய உறுதிப்பாட்டுக்கு முன் இருவரும் பொறுப்பின் அளவைத் தெரிந்திருக்க வேண்டும்.'],
 ['Long-term stability comes from repeated repair, fairness and reliability rather than one favourable horoscope factor. Review recurring problems before they become a fixed pattern.','நீண்டகால நிலைத்தன்மை ஒரு நல்ல ஜாதக காரணியால் மட்டும் வராது; மீண்டும் மீண்டும் சமரசம் செய்தல், நியாயம் மற்றும் நம்பகத்தன்மை மூலம் வளர்கிறது. ஒரே பிரச்சினை மீண்டும் வந்தால் அது பழக்கமாக மாறுவதற்கு முன் சரிசெய்ய வேண்டும்.'],
 ['D9 should be read as how the relationship matures under responsibility. With time, the stronger outcome comes from realistic expectations, clearer boundaries and shared duty—not from assuming harmony will happen automatically.','D9-ஐ பொறுப்புகளுக்குள் உறவு எப்படி முதிர்கிறது என்பதைக் காட்டும் அடுக்காக வாசிக்க வேண்டும். காலத்தோடு நல்ல பலன் கிடைக்க வேண்டுமெனில் நடைமுறை எதிர்பார்ப்பு, தெளிவான எல்லைகள் மற்றும் பகிரப்பட்ட பொறுப்பு வளர வேண்டும்; ஒற்றுமை தானாக வரும் என்று மட்டும் கருதக்கூடாது.']
];
function mmHumanBalanceNarrative(B,G,i=0){
 const bb=mmHumanBand(B.score),gb=mmHumanBand(G.score),diff=Number(B.score||0)-Number(G.score||0),pick=a=>a[Math.abs(Number(i)||0)%a.length];
 if(bb==='good'&&gb==='good')return T(pick(['Both charts support this area independently; the natural base is useful, and daily consistency determines how much of that promise is actually enjoyed.','This is one of the easier areas for the pair: both charts contribute usable support, so problems here are more likely to be solved than allowed to accumulate.','There is real support on both sides here. The relationship benefits most when that strength is used cooperatively rather than taken for granted.','Both individuals carry enough support in this area for it to become a stabilising part of married life, provided the same standard is maintained in behaviour.']),pick(['இந்த அம்சத்தில் இரு ஜாதகங்களுமே தனித்தனி ஆதரவு தருகின்றன; நல்ல அடித்தளம் இருப்பதால் தினசரி நடத்தை சரியாக இருந்தால் அந்த பலன் முழுமையாக அனுபவிக்க முடியும்.','இது இருவருக்கும் ஒப்பீட்டளவில் எளிதாகச் செயல்படக்கூடிய பகுதி; சிக்கல் வந்தாலும் சேர்ந்து தீர்க்கும் ஆதாரம் இரு பக்கத்திலும் உள்ளது.','இருபுறமும் உண்மையான ஆதரவு உள்ளது. அதை இயல்பாக கிடைத்த பலன் என்று அலட்சியம் செய்யாமல் கூட்டாக பயன்படுத்தினால் உறவுக்கு நிலைத்தன்மை தரும்.','இந்த அம்சம் நீண்டகால திருமண வாழ்க்கைக்கு ஒரு stabilising factor ஆக மாறக்கூடிய அளவு இரு ஜாதகங்களிலும் ஆதரவு உள்ளது; அதே தரமான நடத்தை தொடர்ந்து இருக்க வேண்டும்.']));
 if(bb==='care'&&gb==='care')return T(pick(['Both charts repeat pressure in this area, so the issue can echo from both sides. A conscious rule or routine is more useful than waiting for the other person to change first.','This is a genuine shared pressure point. The same theme can recur until the couple deliberately changes the way it is handled.','Neither chart carries enough effortless ease here; progress comes through maturity, clear boundaries and repeated correction rather than expectation alone.','Pressure appears on both sides, which makes this an area for deliberate management. It need not damage the relationship if it is recognised early and handled consistently.']),pick(['இந்த அம்சத்தில் இரு பக்கத்திலும் அழுத்தம் மீண்டும் வருகிறது; மற்றவர் முதலில் மாற வேண்டும் என்று காத்திருக்காமல் இருவரும் ஏற்ற ஒரு நடைமுறை விதி அமைப்பது பயனுள்ளதாக இருக்கும்.','இது உண்மையான shared pressure point. இதை கையாளும் முறையை இருவரும் திட்டமிட்டு மாற்றும் வரை ஒரே விஷயம் மீண்டும் வரக்கூடும்.','இந்த பகுதியில் தானாக வரும் எளிமை குறைவு; தெளிவான எல்லைகள், முதிர்ச்சி மற்றும் மீண்டும் மீண்டும் செய்யும் திருத்தமே நல்ல பலனை உருவாக்கும்.','இரு ஜாதகங்களிலும் அழுத்தம் இருப்பதால் இந்தப் பகுதியை விழிப்புணர்வுடன் கையாள வேண்டும். ஆரம்பத்திலேயே புரிந்து கொண்டு தொடர்ந்து சரிசெய்தால் அது உறவை கெடுக்க வேண்டிய அவசியமில்லை.']));
 if(bb!==gb||Math.abs(diff)>=1.25){const who=diff>0?T('Bride','பெண்'):T('Groom','ஆண்');return T(pick([`${who} carries more natural support here. That person can steady the relationship, but should not use the stronger position to dominate the other.`,`${who} is better equipped for this area in the chart. Married life improves when that strength is used to absorb pressure and explain, not to judge.`,`${who} has the clearer supportive pattern here; the other side may need time or adjustment. The difference is manageable when responsibility is shared fairly.`,`${who} has more astrological support in this matter. The practical task is to turn that difference into balance rather than a superior/inferior dynamic.`]),pick([`${who} பக்கத்தில் இங்கு இயல்பான ஆதரவு அதிகம். அந்த பலத்தை உறவை நிலைப்படுத்த பயன்படுத்தலாம்; மற்றவரை கட்டுப்படுத்தும் நிலையாக மாற்றக்கூடாது.`,`${who} பக்கம் இந்த அம்சத்தை கையாளும் திறன் அதிகமாக தெரிகிறது. தீர்ப்பளிப்பதை விட அழுத்தத்தை absorb செய்து விளக்குவதற்கு அந்த பலத்தை பயன்படுத்தினால் இல்லறம் மேம்படும்.`,`${who} பக்கம் தெளிவான ஆதரவு உள்ளது; மற்ற பக்கத்திற்கு காலம் அல்லது சமரசம் தேவைப்படலாம். பொறுப்பு நியாயமாகப் பகிரப்பட்டால் இந்த வேறுபாடு கையாளக்கூடியது.`,`${who} பக்கத்தில் இந்த விஷயத்திற்கு ஜாதக ஆதரவு அதிகம். அந்த வேறுபாட்டை மேல்/கீழ் நிலையாக அல்லாமல் சமநிலையாக மாற்றுவதுதான் நடைமுறை பணியாகும்.`]));}
 return T(pick(['The two charts are comparably mixed here. There is enough support to work with, but habits and communication will decide whether the better or harder side becomes dominant.','This area is neither an automatic strength nor a serious denial. The couple’s routine choices determine how the mixed promise matures.','Both charts show a workable but mixed pattern. The issue becomes easier when expectations are made explicit before pressure builds.','The astrology is balanced enough to work, but not effortless. Repeated behaviour will matter more than a one-time promise or one favourable factor.']),pick(['இந்த அம்சத்தில் இரு ஜாதகங்களும் ஒப்பிடத்தக்க கலப்பு நிலை. ஆதரவு உள்ளது; ஆனால் நல்ல பக்கமா சவால் பக்கமா மேலெழும் என்பதை பழக்கம் மற்றும் உரையாடல் தீர்மானிக்கும்.','இது தானாகவே பெரிய பலமோ பெரிய மறுப்போ அல்ல. தினசரி தேர்வுகள் இந்த கலப்பு பலன் எந்தத் திசையில் முதிர்கிறது என்பதை முடிவு செய்யும்.','இரு ஜாதகங்களும் கையாளக்கூடிய கலப்பு pattern தருகின்றன. அழுத்தம் பெரிதாகும் முன் எதிர்பார்ப்புகளை தெளிவுபடுத்தினால் இந்த பகுதி எளிதாகும்.','ஜாதக ரீதியாக இந்த பகுதி வேலை செய்யக்கூடிய சமநிலையில் உள்ளது; ஆனால் முயற்சியில்லாமல் இயங்காது. ஒருமுறை கூறும் வாக்குறுதியை விட மீண்டும் வரும் நடத்தை அதிகம் தீர்மானிக்கும்.']));
}
// Original bilingual interpretation: compare actual D1/D9 evidence, not a generic score paragraph.
function mm239PlacementStory(profile,topic,who){
 const layer=profile.d1;if(!layer)return T(`${who}: D1 placements are unavailable; no individual reading is assigned.`,`${who}: D1 நிலைகள் கிடைக்காததால் தனிப்பட்ட பலன் கூறப்படவில்லை.`);
 const h=topic.houses?.[0]||7,lord=mmHumanHouseLord(layer,h),p=mmHumanPlanet(layer,lord);if(!p)return T(`${who}: the relevant house-lord position is missing.`,`${who}: தொடர்புடைய பாவ அதிபதியின் நிலை கிடைக்கவில்லை.`);
 const ph=house(p.longitude,layer.lag),paths={
 1:['personal choices and the way needs are expressed','தனிப்பட்ட முடிவும் தேவையை வெளிப்படுத்தும் முறையும்'],
 2:['family expectations, words and shared spending','குடும்ப எதிர்பார்ப்பு, பேச்சு மற்றும் பகிர்ந்த செலவும்'],
 3:['daily conversations and willingness to take initiative','அன்றாட உரையாடலும் முன்வந்து செயல்படும் மனமும்'],
 4:['home arrangements and emotional security','வீட்டு ஒழுங்கும் மனப் பாதுகாப்பும்'],
 5:['affection, leisure and attention given to children','அன்பு, ஓய்வு நேரம் மற்றும் குழந்தைகளுக்குக் கொடுக்கும் கவனமும்'],
 6:['workload and the division of ordinary duties','வேலைச்சுமையும் அன்றாடக் கடமைகளைப் பகிர்வதும்'],
 7:['direct discussion and the partner’s participation','நேரடியான உரையாடலும் துணைவரின் பங்கேற்பும்'],
 8:['privacy, trust and shared obligations','தனியுரிமை, நம்பிக்கை மற்றும் பகிர்ந்த பொறுப்பும்'],
 9:['values, family traditions and advice from elders','மதிப்புகள், குடும்ப மரபு மற்றும் பெரியோரின் ஆலோசனையும்'],
 10:['career commitments and public responsibilities','தொழில் சார்ந்த கடமையும் வெளிப்புறப் பொறுப்பும்'],
 11:['common goals, friends and mutual support','பொது இலக்கு, நண்பர்கள் மற்றும் பரஸ்பர ஆதரவும்'],
 12:['private time, distance and the need for rest','தனிப்பட்ட நேரம், இடைவெளி மற்றும் ஓய்வுத் தேவையும்']};
 const link=paths[ph];let out=T(`${who}: the lord of house ${h}, ${mmHumanPlanetLabel(lord)}, is in house ${ph} (${sign(si(p.longitude))}). For ${topic.en.toLowerCase()}, this makes ${link?.[0]||'the corresponding life area'} especially relevant.`,`${who}: ${h}-ஆம் பாவ அதிபதி ${mmHumanPlanetLabel(lord)} ${sign(si(p.longitude))} ராசியில் ${ph}-ஆம் பாவத்தில் உள்ளது. ${topic.ta} விஷயத்தில் ${link?.[1]||'தொடர்புடைய வாழ்க்கைப் பகுதியும்'} முக்கிய பங்காற்றலாம்.`);
 const d=mmHumanDignityDelta(lord,p.longitude);if(d>0)out+=' '+T('The lord has own-sign or exaltation support, giving a stronger basis for handling this need consistently.','அதிபதிக்கு சுயராசி அல்லது உச்ச ஆதரவு இருப்பதால் இந்தத் தேவையைத் தொடர்ந்து கையாளும் அடித்தளம் வலுவாக உள்ளது.');else if(d<0)out+=' '+T('The lord is debilitated, so expressing this need may require more conscious effort; other supporting factors still matter.','அதிபதி நீச நிலையில் இருப்பதால் இந்தத் தேவையை வெளிப்படுத்துவதில் கூடுதல் முயற்சி தேவைப்படலாம்; மற்ற ஆதரவுகளையும் சேர்த்தே பார்க்க வேண்டும்.');
 const vg=profile.d9;if(vg){const vl=mmHumanHouseLord(vg,h),vp=mmHumanPlanet(vg,vl);if(vp){const vh=house(vp.longitude,vg.lag),vd=mmHumanDignityDelta(vl,vp.longitude);out+=' '+T(`In D9 the same house is ruled by ${mmHumanPlanetLabel(vl)}, placed in house ${vh}. ${vd>0?'Its sign dignity adds support.':vd<0?'Its weaker sign dignity adds an adjustment point.':'Its ordinary sign dignity does not establish extra support by itself.'}`,`D9 இல் இதே பாவ அதிபதி ${mmHumanPlanetLabel(vl)} ${vh}-ஆம் பாவத்தில் உள்ளது. ${vd>0?'அதன் ராசிப் பலம் கூடுதல் ஆதரவு தருகிறது.':vd<0?'அதன் குறைந்த ராசிப் பலம் கூடுதல் கவனத்தைக் கேட்கிறது.':'அதன் சாதாரண ராசிநிலையை மட்டும் கூடுதல் ஆதரவாக எடுத்துக்கொள்ளவில்லை.'}`);}}
 return out;
}
function mm239PairBalance(topic,B,G){const bb=mmHumanBand(B.score),gb=mmHumanBand(G.score);if(!B.d1||!G.d1)return T('The missing chart prevents a balanced comparison of the two people.','ஒருவரின் ஜாதகத் தரவு இல்லாததால் இருவரையும் சமமாக ஒப்பிட முடியவில்லை.');if(bb==='good'&&gb==='good')return T(topic.good[0],topic.good[1]);if(bb==='care'&&gb==='care')return T(topic.care[0],topic.care[1]);if(bb===gb)return T(`The combined indications for ${topic.en.toLowerCase()} are mixed: there is room for cooperation, but it should not be assumed to happen without discussion.`,`இருவருக்கும் ${topic.ta} பகுதியில் கலப்பான சுட்டிகள் உள்ளன; ஒத்துழைக்க வாய்ப்பு இருந்தாலும் பேசாமலேயே புரிந்துகொள்வார்கள் என்று எதிர்பார்க்க வேண்டாம்.`);const who=B.score>G.score?T('bride','பெண்'):T('groom','ஆண்');return T(`The ${who}'s chart has relatively more support for ${topic.en.toLowerCase()}. That difference is useful when responsibilities are shared by agreement; it does not make one person responsible for managing the other.`,`${topic.ta} பகுதியில் ${who} ஜாதகத்தில் ஒப்பீட்டளவில் ஆதரவு அதிகம். பொறுப்பை இருவரும் பேசி பகிர்ந்தால் இது உதவியாக அமையும்; ஒருவரே மற்றவரின் எல்லாத் தேவையையும் ஏற்க வேண்டும் என்பதல்ல.`);}

function mmHumanDetailedText(topic,B,G,bs,gs,i){const guide=MM_HUMAN_GUIDANCE[i]||['',''];return [mm239PlacementStory(B,topic,T('Bride','பெண்')),mm239PlacementStory(G,topic,T('Groom','ஆண்')),mm239PairBalance(topic,B,G),T(guide[0],guide[1])].filter(Boolean).join(' ');}
function mmHumanLagnaEvidence(c){const d1=mmHumanLayer(c,1);if(!d1)return T('D1 Lagna data unavailable','D1 லக்ன தரவு இல்லை');const li=si(d1.lag),lord=LORD[li],lp=mmHumanPlanet(d1,lord),bits=[`${T('Lagna','லக்னம்')}: ${sign(li)}`];if(lp)bits.push(`${T('Lagna lord','லக்ன அதிபதி')} ${mmHumanPlanetLabel(lord)} — ${T('house','பாவம்')} ${house(lp.longitude,d1.lag)}, ${dignity(lord,lp.longitude)}`);const occ=d1.planets.filter(p=>house(p.longitude,d1.lag)===1).map(p=>Object.keys(MM_PLANET_LABEL).find(k=>mmPlanetMatches(p?.name,k))).filter(Boolean);if(occ.length)bits.push(`${T('Planets in Lagna','லக்னத்தில் உள்ள கிரகங்கள்')}: ${occ.map(mmHumanPlanetLabel).join(', ')}`);return bits.join(' · ');}
function mmUniqueEvidence(list,limit=4){const seen=new Set(),out=[];for(const x of list){const k=String(x||'').replace(/\s+/g,' ').trim();if(!k||seen.has(k))continue;seen.add(k);out.push(k);if(out.length>=limit)break;}return out;}
function marriageHumanD1D9Panel(b,g){
 const profiles=MM_HUMAN_TOPICS.map((topic,i)=>{
  const B=mmHumanTopicProfile(b,topic),G=mmHumanTopicProfile(g,topic),bs=mmHumanElementStyle(b,topic),gs=mmHumanElementStyle(g,topic);
  return {topic,i,B,G,bs,gs,band:mmHumanBand((Number(B.score||0)+Number(G.score||0))/2)};
 });
 const supportive=profiles.filter(x=>x.band==='good').length,care=profiles.filter(x=>x.band==='care').length,mixed=profiles.length-supportive-care;
 const overview=lang()==='ta'
  ?`இந்த 25 வாழ்க்கைத் தலைப்புகளில் ${supportive} பகுதிகளில் தெளிவான ஆதரவு, ${mixed} பகுதிகளில் கலப்பு/சமரச நிலை, ${care} பகுதிகளில் கூடுதல் கவனம் தேவைப்படும் அமைப்பு தெரிகிறது. இதை “எத்தனை நல்லது / எத்தனை கெட்டது” என்ற எண்ணிக்கையாக மட்டும் வாசிக்காமல், நல்ல பகுதிகள் எந்த சவால்களை சமநிலைப்படுத்துகின்றன என்பதையும் சேர்த்து பார்க்க வேண்டும்.`
  :`Across these 25 life areas, ${supportive} show clearer support, ${mixed} are mixed/workable, and ${care} need more conscious attention. This should not be reduced to a good-versus-bad count; the useful question is how the supportive areas can help the couple manage the demanding ones.`;
 const rows=profiles.map(({topic,i,B,G,bs,gs})=>{
  const guide=MM_HUMAN_GUIDANCE[i]||['',''];const human=[mm239PlacementStory(B,topic,T('Bride','பெண்')),mm239PlacementStory(G,topic,T('Groom','ஆண்')),mm239PairBalance(topic,B,G),T(guide[0],guide[1])].filter(Boolean);
  const evidence=mmUniqueEvidence([...(i===0?[`${T('Bride','பெண்')}: ${mmHumanLagnaEvidence(b)}`,`${T('Groom','ஆண்')}: ${mmHumanLagnaEvidence(g)}`]:[]),...B.evidence.map(x=>`${T('Bride','பெண்')}: ${x}`),...G.evidence.map(x=>`${T('Groom','ஆண்')}: ${x}`)],4);
  return `<div class="mm-human-topic"><h4>${i+1}. ${T(topic.en,topic.ta)}</h4>${human.map(p=>`<p>${esc(p)}</p>`).join('')}<details class="mm-human-evidence mm-technical-evidence" data-print-technical="1"><summary>${T('Chart basis','ஜாதக ஆதாரம்')}</summary><p class="mm-note">${evidence.length?evidence.map(esc).join('<br>'):T('Only the available D1/D9 factors were used; missing factors were not invented.','கிடைத்த D1/D9 காரணிகள் மட்டும் பயன்படுத்தப்பட்டன; இல்லாத தரவு கற்பனை செய்யப்படவில்லை.')}</p></details></div>`;
 }).join('');
 return `<section class="mm-person-result mm-human-d1d9"><h3>${T('D1 + D9 Detailed Human Marriage-Life Reading — 25 Areas','D1 + D9 விரிவான மனித திருமண வாழ்க்கை வாசிப்பு — 25 தலைப்புகள்')}</h3><p>${esc(overview)}</p>${rows}</section>`;
}



function marriageCompatibilityOverviewPanel(b,g,pr,ks,sync,v){
 const kb=kujaVilakku(ks.B,ks.G),kg=kujaVilakku(ks.G,ks.B),rb=rahuVilakku(sync.br),rg=rahuVilakku(sync.gr),nv=nadiVilakku(pr,b,g),rj=rajjuVilakku(pr),m=marriageStrengthMatrix(b,g),bk=kalaSarpaAssessment(b),gk=kalaSarpaAssessment(g),nb=nagaDoshaAssessment(b),ng=nagaDoshaAssessment(g);
 const good=pr.rows.filter(x=>x[1]).map(x=>x[0]),weak=pr.rows.filter(x=>!x[1]).map(x=>x[0]),support=[],care=[];
 if(pr.score>=7)support.push(T('The Nakshatra layer gives a generally workable day-to-day base.','நட்சத்திரப் பொருத்தம் அன்றாட வாழ்க்கைக்கு பொதுவாக கையாளக்கூடிய நல்ல அடித்தளத்தை தருகிறது.'));
 if(m.B.balance>=1&&m.G.balance>=1)support.push(T('Both individual charts retain marriage-support strength after 7th-house/D9 weighting.','7-ஆம் பாவம்/D9 weighting பிறகு இரு தனி ஜாதகங்களிலும் திருமண ஆதரவு பலம் உள்ளது.'));
 if(ks.balanced)support.push(T('Mars/Kuja pressure is broadly comparable, so one-sided temperament pressure is reduced.','செவ்வாய்/குஜ தாக்கம் இருவருக்கும் பொதுவாக ஒப்பிடத்தக்கதால் ஒருபுற குணநிலை அழுத்தம் குறைகிறது.'));
 if(pr.score<6)care.push(T('Nakshatra support is limited and should not be used alone.','நட்சத்திர ஆதரவு குறைவாக இருப்பதால் அதை மட்டும் வைத்து முடிவு செய்யக்கூடாது.'));
 if(['active','strong'].includes(nv.state))care.push(T('Nadi remains active after the available exception checks.','கிடைக்கும் விதிவிலக்கு ஆய்வுக்குப் பிறகும் நாடி நிலை செயலில் உள்ளது.'));
 if(['active','strong','consult'].includes(kb.state)||['active','strong','consult'].includes(kg.state)||!ks.balanced)care.push(T('Residual Kuja imbalance needs conscious conflict-management and partner-balance review.','மீதமுள்ள செவ்வாய் சமமின்மை கருத்து மோதலை கையாளும் விதம் மற்றும் இருவர் சமநிலையை நெருக்கமாகப் பார்க்க வேண்டும்.'));
 if(['active','complex'].includes(rb.state)||['active','complex'].includes(rg.state))care.push(T('A residual Rahu–Ketu relationship-axis condition needs trust, clarity and timing review.','மீதமுள்ள ராகு–கேது உறவு அச்சு நிலைக்கு நம்பிக்கை, தெளிவு மற்றும் கால ஆய்வு தேவை.'));
 if(rj.state==='active'||rj.state==='strong'||rj.state==='consult')care.push(T('Rajju requires its exception/protection context to be respected in the final judgement.','ரஜ்ஜு நிலைக்கு பொருந்தும் விதிவிலக்கு/பாதுகாப்பு சூழலை இறுதி முடிவில் கவனிக்க வேண்டும்.'));
 if(bk.present||gk.present)care.push(T('Kala Sarpa is present in at least one chart; it is a whole-chart modifier, not an automatic rejection.','குறைந்தது ஒரு ஜாதகத்தில் கால சர்ப்ப அமைப்பு உள்ளது; அது முழு ஜாதகத்தை மாற்றிப் படிக்க வேண்டிய சூழல் காரணம் மட்டுமே, தானாக நிராகரிப்பு அல்ல.'));
 if(['active','strong'].includes(nb.state)||['active','strong'].includes(ng.state))care.push(T('A Naga/Sarpa pattern is active in at least one chart. Read it separately from Kala Sarpa and judge it through the 5th house/lord, Jupiter, nodes and D7 protection rather than treating it as an automatic marriage veto.','குறைந்தது ஒரு ஜாதகத்தில் நாக/சர்ப்ப அமைப்பு செயலில் உள்ளது. இதை கால சர்ப்பத்திலிருந்து தனியாக வைத்து, 5-ஆம் பாவம்/அதிபதி, குரு, ராகு–கேது மற்றும் D7 பாதுகாப்புடன் சேர்த்து பார்க்க வேண்டும்; தானாக திருமணத் தடை என்று எடுத்துக்கொள்ளக் கூடாது.'));
 const headline=v.k==='match'?T('The charts have a workable marriage foundation after the available balancing checks.','கிடைக்கும் சமநிலை/விலக்கு ஆய்வுகளுக்குப் பிறகு இந்த இரு ஜாதகங்களுக்கும் திருமணத்திற்கு கையாளக்கூடிய நல்ல அடித்தளம் உள்ளது.'):v.k==='consult'?T('There is meaningful compatibility, but a few unresolved factors need an astrologer to weigh support, dosha balance and timing together.','குறிப்பிடத்தக்க நல்ல பொருத்தம் உள்ளது; ஆனால் சில தீராத காரணிகள் இருப்பதால் ஆதரவு, தோஷ சமநிலை மற்றும் காலத்தை ஒன்றாக வைத்து ஜோதிடர் இறுதி முடிவு செய்ய வேண்டும்.'):T('Several major traditional conflicts remain after the available balancing checks; this needs careful personal review rather than a score-only decision.','கிடைக்கும் சமநிலை/விலக்கு ஆய்வுகளுக்குப் பிறகும் சில முக்கிய பாரம்பரிய முரண்பாடுகள் மீதமுள்ளன; மதிப்பெண் மட்டும் வைத்து அல்லாமல் தனிப்பட்ட விரிவான ஆய்வு தேவை.');
 const row=(t,a)=>`<div><b>${esc(t)}</b><span>${(a.length?a:[T('No major item isolated.','முக்கிய காரணம் தனியாக இல்லை.')]).map(x=>'• '+esc(x)).join('<br>')}</span></div>`;
 return `<section class="mm-person-result mm-marriage-first"><h3>${T('Marriage Compatibility — Astrologer Reading','திருமணப் பொருத்தம் — ஜோதிடர் வாசிப்பு')}</h3><p><b>${esc(v.label)}</b></p><p>${esc(headline)}</p><div class="mm-facts"><div><b>${T('Nakshatra foundation','நட்சத்திர அடித்தளம்')}</b><span>${pr.score}/10 · ${T('Supportive','ஆதரவு')}: ${esc(good.slice(0,6).join(', ')||'—')}<br>${T('Needs adjustment/review','சமரசம்/ஆய்வு')}: ${esc(weak.slice(0,6).join(', ')||'—')}</span></div>${row(T('What supports the marriage','திருமணத்தை ஆதரிக்கும் அம்சங்கள்'),support)}${row(T('What needs conscious attention','கவனமாக கையாள வேண்டிய அம்சங்கள்'),care)}<div><b>${T('Couple-level conclusion','இருவர் ஒருங்கிணைந்த முடிவு')}</b><span>${esc(m.couple)}</span></div></div></section>`;
}
function nodeDoshaHumanPanel(b,g,sync){
 const one=(who,c,r)=>{const rv=rahuVilakku(r),k=kalaSarpaAssessment(c),n=nagaDoshaAssessment(c);let rel;if(['active','complex'].includes(rv.state))rel=T('The nodal pattern can intensify trust, expectation, attraction/aversion and major relationship decisions. Its severity is read only after checking the 7th lord, Venus/Jupiter and D9 protection.','ராகு–கேது அமைப்பு நம்பிக்கை, எதிர்பார்ப்பு, ஈர்ப்பு/விலகல் மற்றும் பெரிய உறவு முடிவுகளை தீவிரமாக உணரச் செய்யலாம். 7-ஆம் அதிபதி, சுக்கிரன்/குரு மற்றும் D9 பாதுகாப்பை பார்த்த பின்பே அதன் கடுமை முடிவு செய்யப்படுகிறது.');else rel=T('The available protection checks do not leave a strong residual Rahu–Ketu marriage-axis pressure.','கிடைக்கும் பாதுகாப்பு ஆய்வுக்குப் பிறகு வலுவான மீதமுள்ள ராகு–கேது திருமண அச்சு அழுத்தம் தெரியவில்லை.');const nagaHits=n.hits?.length?`<br>${esc(T('Why this level: ','இந்த நிலைக்கு காரணம்: ')+n.hits.join('; '))}`:'';return `<div><b>${esc(who)} · ${T('Rahu–Ketu marriage axis','ராகு–கேது திருமண அச்சு')}</b><span>${esc(rv.label)}${r.hits?.length?' · '+esc(r.hits.join(', ')):''}<br>${esc(rel)}</span></div><div><b>${esc(who)} · ${T('Kala Sarpa Yoga','கால சர்ப்ப யோகம்')}</b><span>${esc(k.text)}<br>${esc(T('Kala Sarpa is a whole-chart configuration and is never used here as an automatic marriage rejection.','கால சர்ப்பம் முழு ஜாதக அமைப்பு; இதை தானாக திருமண நிராகரிப்பாக பயன்படுத்தப்படாது.'))}</span></div><div><b>${esc(who)} · ${T('Naga / Sarpa Dosha','நாக / சர்ப்ப தோஷம்')}</b><span><b>${esc(n.label)}</b><br>${esc(n.text)}${nagaHits}</span></div>`;};
 return `<section class="mm-person-result mm-node-dosha"><h3>${T('Rahu–Ketu, Kala Sarpa & Naga/Sarpa — Detailed Reading','ராகு–கேது, கால சர்ப்பம் & நாக/சர்ப்ப தோஷம் — விரிவான வாசிப்பு')}</h3><p>${T('Rahu–Ketu can affect trust, attachment, sudden attraction/withdrawal and the timing of major relationship decisions. Kala Sarpa is a separate whole-chart pattern. Naga/Sarpa traditions focus more on node pressure around progeny/family and marriage-sensitive houses. The reading below shows whether the pattern is mild, active or strongly repeated and also notes the factors that reduce it.','ராகு–கேது நம்பிக்கை, பற்றுதல், திடீர் ஈர்ப்பு/விலகல் மற்றும் பெரிய உறவு முடிவுகளின் காலத்தை தீவிரமாக்கலாம். கால சர்ப்பம் இதிலிருந்து தனியான முழு ஜாதக அமைப்பு. நாக/சர்ப்ப மரபுகள் குழந்தை/குடும்ப மற்றும் திருமணத்துடன் தொடர்புடைய பாவங்களில் node அழுத்தத்தை அதிகமாகக் கவனிக்கின்றன. கீழுள்ள வாசிப்பு அந்த அமைப்பு மிதமா, செயலில் உள்ளதா, வலுவாக மீண்டும் வருகிறதா என்பதையும் அதை குறைக்கும் பாதுகாப்பு காரணிகளையும் காட்டுகிறது.')}</p><div class="mm-facts">${one(T('Bride','பெண்'),b,sync.br)}${one(T('Groom','ஆண்'),g,sync.gr)}</div><details class="mm-technical-evidence" data-print-technical="1"><summary>${T('View node/dosha calculation rule','node / தோஷ கணக்கீட்டு விதி பார்க்க')}</summary><p class="mm-note">${T('Naga/Sarpa severity uses transparent weighted triggers: node contact with the 5th house or 5th lord, 1/7–2/8–5/11 node axes, close node contacts with Jupiter/Moon/Venus, and protection from a strong 5th lord, Jupiter and available D7. No node aspect convention is invented where traditions disagree.','நாக/சர்ப்ப கடுமை வெளிப்படையான weighted trigger-களால் கணிக்கப்படுகிறது: 5-ஆம் பாவம் அல்லது 5-ஆம் அதிபதியுடன் node தொடர்பு, 1/7–2/8–5/11 node அச்சுகள், குரு/சந்திரன்/சுக்கிரனுடன் நெருக்கமான node இணைவு, மேலும் வலுவான 5-ஆம் அதிபதி, குரு மற்றும் கிடைக்கும் D7 பாதுகாப்பு. மரபுகள் மாறும் இடங்களில் புதிய node பார்வை விதி கற்பனை செய்யப்படவில்லை.')}</p></details></section>`;
}
function marriageRemedyPlanPanel(b,g,pr,ks,sync){
 const kb=kujaVilakku(ks.B,ks.G),kg=kujaVilakku(ks.G,ks.B),rb=rahuVilakku(sync.br),rg=rahuVilakku(sync.gr),nv=nadiVilakku(pr,b,g),rj=rajjuVilakku(pr),bk=kalaSarpaAssessment(b),gk=kalaSarpaAssessment(g),nb=nagaDoshaAssessment(b),ng=nagaDoshaAssessment(g),B=structuredLagnaDoshas(b),G=structuredLagnaDoshas(g);const life=[],worship=[],discipline=[],avoid=[];const add=(a,x)=>{if(x&&!a.includes(x))a.push(x)};
 const activeKuja=['active','strong','partial','consult'].includes(kb.state)||['active','strong','partial','consult'].includes(kg.state);const activeNaga=['mild','active','strong'].includes(nb.state)||['mild','active','strong'].includes(ng.state);const activeNode=['active','complex'].includes(rb.state)||['active','complex'].includes(rg.state)||bk.present||gk.present||activeNaga;const activeMarriage=['mangalya','sukra','kalathra'].some(k=>(B[k]?.finalLevel||0)>0||(G[k]?.finalLevel||0)>0);const activePutra=(B.putra?.finalLevel||0)>0||(G.putra?.finalLevel||0)>0;
 add(life,T('Keep one fixed weekly time for calm discussion of money, family expectations, work pressure and decisions; do not wait until conflict becomes intense.','பணம், குடும்ப எதிர்பார்ப்பு, வேலை அழுத்தம் மற்றும் முக்கிய முடிவுகளை அமைதியாகப் பேச வாரத்திற்கு ஒரு நிரந்தர நேரம் வைத்துக் கொள்ளுங்கள்; மோதல் பெரிதாகும் வரை காத்திருக்க வேண்டாம்.'));
 if(activeKuja)add(life,T('For Mars-related pressure, use a cooling-off rule: pause arguments, avoid decisions in anger and return to the issue after both are calm.','செவ்வாய் சார்ந்த அழுத்தத்திற்கு “cooling-off” முறையைப் பயன்படுத்துங்கள்: கோபத்தில் விவாதத்தை நிறுத்தி, பெரிய முடிவுகளை எடுக்காமல், இருவரும் அமைதியான பிறகு மீண்டும் பேசுங்கள்.'));
 if(activeNode)add(life,T('For Rahu/Ketu or Kala Sarpa context, avoid secrecy, fear-driven conclusions and sudden relationship decisions; verify facts and keep major choices transparent.','ராகு/கேது அல்லது கால சர்ப்ப சூழலில் மறைவு, பயம் சார்ந்த முடிவு மற்றும் திடீர் உறவு முடிவுகளைத் தவிர்த்து, உண்மைகளை சரிபார்த்து முக்கிய முடிவுகளை வெளிப்படையாக எடுக்கவும்.'));
 if(activeMarriage)add(life,T('For Kalathra/Venus/Mangalya residuals, strengthen mutual respect, consent, financial transparency, family boundaries and shared decision-making.','களத்திர/சுக்கிர/மாங்கல்ய மீதமுள்ள நிலைகளில் பரஸ்பர மரியாதை, சம்மதம், நிதி வெளிப்படைத்தன்மை, குடும்ப எல்லைகள் மற்றும் கூட்டு முடிவெடுப்பை வலுப்படுத்துங்கள்.'));
 if(activePutra)add(life,T('For Putra/family-expansion concerns, plan together and use qualified medical advice for fertility or health questions; astrology should not replace diagnosis.','புத்திர/குடும்ப விரிவு கவலைகளில் இருவரும் திட்டமிட்டு, கருத்தரிப்பு அல்லது உடல்நல கேள்விகளுக்கு தகுதியான மருத்துவ ஆலோசனையைப் பெறுங்கள்; ஜோதிடம் நோயறிதலுக்கு மாற்றாகாது.'));
 if(activeKuja)add(worship,T('Mars: Tuesday Murugan/Subrahmanya or Angaraka/Navagraha prayer, together with disciplined service or charity, according to family tradition.','செவ்வாய்: குடும்ப மரபுப்படி செவ்வாய்க்கிழமை முருகன்/சுப்பிரமணியர் அல்லது அங்காரக/நவகிரக வழிபாடு; அதனுடன் ஒழுங்கான சேவை அல்லது தானம்.'));
 if(['active','complex'].includes(rb.state)||['active','complex'].includes(rg.state))add(worship,T('Rahu: Durga or Rahu/Navagraha worship according to family tradition; use the practice to cultivate clarity rather than fear.','ராகு: குடும்ப மரபுப்படி துர்கை அல்லது ராகு/நவகிரக வழிபாடு; பயத்தை அதிகரிக்காமல் தெளிவை வளர்க்கும் பக்தி முறையாக பயன்படுத்துங்கள்.'));
 if(bk.present||gk.present)add(worship,T('Kala Sarpa / strong nodal context: Ganesha, Subrahmanya or Navagraha worship may be followed according to family tradition, together with transparent practical decisions and disciplined routine.','கால சர்ப்ப / வலுவான node சூழலில் குடும்ப மரபுப்படி விநாயகர், சுப்பிரமணியர் அல்லது நவகிரக வழிபாட்டை பின்பற்றலாம்; அதனுடன் வெளிப்படையான நடைமுறை முடிவும் ஒழுங்கான வாழ்க்கை முறையும் இணைக்க வேண்டும்.'));
 if(activeNaga){add(life,T('For an active Naga/Sarpa pattern, do not let fear about marriage or children become the problem itself. Keep medical/fertility care practical where relevant, and treat the astrological pattern as a reason for steadier planning and family communication.','செயலில் உள்ள நாக/சர்ப்ப அமைப்பில் திருமணம் அல்லது குழந்தை பற்றிய பயமே பிரச்சினையாக மாற விடக்கூடாது. தேவையான இடத்தில் மருத்துவ/கருத்தரிப்பு ஆலோசனையை நடைமுறையாகப் பயன்படுத்தி, ஜோதிடச் சுட்டியை திட்டமிட்ட குடும்ப உரையாடல் மற்றும் பொறுப்பான முடிவுக்கான காரணமாக மட்டும் எடுத்துக் கொள்ளுங்கள்.'));add(worship,T('Naga/Sarpa tradition: Subrahmanya/Murugan and Naga-deity worship may be followed according to family tradition. Common South-Indian practices include Ayilyam/Ashlesha or Naga Panchami observance and, where the family priest specifically advises it, temple rites such as Sarpa Samskara/Ashlesha Bali or Naga Pratishtha. Choose an established temple/tradition rather than fear-based commercial promises.','நாக/சர்ப்ப மரபில் குடும்ப வழக்கத்துக்கு ஏற்ப சுப்பிரமணியர்/முருகன் மற்றும் நாக தேவதை வழிபாட்டை பின்பற்றலாம். தென்னிந்திய மரபுகளில் ஆயில்யம்/ஆஸ்லேஷா அல்லது நாக பஞ்சமி வழிபாடு, மேலும் குடும்ப புரோகிதர் குறிப்பாக அறிவுறுத்தினால் சர்ப்ப சம்ஸ்காரம்/ஆஸ்லேஷா பலி அல்லது நாக பிரதிஷ்டை போன்ற கோயில் வழிமுறைகள் செய்யப்படுகின்றன. பயத்தை விற்பனை செய்யும் வணிக உறுதிகளை விட நிலையான கோயில்/குடும்ப மரபைத் தேர்வு செய்ய வேண்டும்.'));}
 if(['active','strong'].includes(nv.state)||['active','strong','consult'].includes(rj.state))add(worship,T('Nadi/Rajju residuals: Shiva–Parvati or family-deity prayer, abhisheka or charity may be followed as a traditional marriage-harmony practice.','நாடி/ரஜ்ஜு மீதமுள்ள நிலைகளில் சிவ–பார்வதி அல்லது குலதெய்வ வழிபாடு, அபிஷேகம் அல்லது தானத்தை திருமண ஒற்றுமைக்கான பாரம்பரிய நடைமுறையாக பின்பற்றலாம்.'));
 if(activePutra)add(worship,T('Putra/Jupiter context: Guru/Dakshinamurti prayer and education/food charity may be followed devotionally; medical care remains primary for fertility concerns.','புத்திர/குரு சூழலில் குரு/தட்சிணாமூர்த்தி வழிபாடு மற்றும் கல்வி/அன்னதானம் போன்ற தானம் பக்தி முறையில் செய்யலாம்; கருத்தரிப்பு கவலைகளில் மருத்துவ ஆலோசனையே முதன்மை.'));
 add(discipline,T('Behaviour modification comes first: change the repeated habit that activates the chart difficulty. Mantra, prayer and meditation are supportive only when daily behaviour also changes.','முதலில் வாழ்வியல் மாற்றமே பரிகாரம்: சவாலை மீண்டும் மீண்டும் தூண்டும் பழக்கத்தை மாற்ற வேண்டும். தினசரி நடத்தை மாறும்போது மட்டுமே மந்திரம், வழிபாடு, தியானம் துணையாக செயல்படும்.'));
 add(discipline,T('If using mantra or a regular devotional practice, choose one sustainable practice and follow it consistently rather than accumulating many fear-driven rituals.','மந்திரம் அல்லது பக்தி வழிமுறையைப் பயன்படுத்தினால் பயத்தால் பல சடங்குகளை சேர்க்காமல், தொடர்ந்து செய்யக்கூடிய ஒரு ஒழுங்கான வழிமுறையைத் தேர்வு செய்யுங்கள்.'));
 add(avoid,T('Do not auto-prescribe gemstones from a single afflicted planet. A gemstone strengthens that planet and can be unsuitable if its functional house ownership is difficult for the Ascendant.','ஒரு பாதிக்கப்பட்ட கிரகத்தை மட்டும் பார்த்து ரத்தினம் தானாக பரிந்துரைக்க வேண்டாம். ரத்தினம் அந்த கிரகத்தை வலுப்படுத்துவதால், லக்னத்திற்கு அந்த கிரகத்தின் பாவ அதிபத்தியம் சிக்கலானதாக இருந்தால் அது பொருத்தமில்லாமல் இருக்கலாம்.'));
 add(avoid,T('Avoid expensive fear-based “dosha removal” promises and do not use astrology as a substitute for medical, legal, fertility or relationship-professional care.','பயம் உருவாக்கும் விலையுயர்ந்த “தோஷ நீக்கம்” உறுதிகளைத் தவிர்க்கவும்; மருத்துவம், சட்டம், கருத்தரிப்பு அல்லது உறவு நிபுணர் உதவிக்கு ஜோதிடத்தை மாற்றாக பயன்படுத்த வேண்டாம்.'));
 const block=(t,a)=>`<div><b>${esc(t)}</b><span>${a.map(x=>'• '+esc(x)).join('<br>')}</span></div>`;
 return `<section class="mm-person-result mm-remedy-plan"><h3>${T('Chart-based Remedy & Married-Life Guidance','ஜாதக அடிப்படையிலான பரிகாரம் & திருமண வாழ்வியல் வழிகாட்டல்')}</h3><p>${T('Remedy is shown only as support for the residual chart pattern. The first remedy is practical behaviour; devotional practice is secondary and should follow family/lineage tradition.','பரிகாரம் என்பது மீதமுள்ள ஜாதக pattern-க்கு துணையாக மட்டுமே காட்டப்படுகிறது. முதல் பரிகாரம் நடைமுறை வாழ்வியல் மாற்றம்; ஆன்மிக/கோயில் வழிபாடு இரண்டாம் நிலை மற்றும் குடும்ப/மரபு வழக்கத்துக்கு ஏற்ப இருக்க வேண்டும்.')}</p><div class="mm-facts">${block(T('Lifestyle correction','வாழ்வியல் திருத்தம்'),life)}${worship.length?block(T('Temple / traditional practice','கோயில் / பாரம்பரிய வழிமுறை'),worship):''}${block(T('Discipline / mantra principle','ஒழுங்கு / மந்திர நடைமுறை'),discipline)}${block(T('What should not be done automatically','தானாக செய்யக்கூடாதவை'),avoid)}</div></section>`;
}
function marriageTechnicalAppendix(b,g,bf,gf,pr,ks,ds,sync,gochar,ku,sand){return `<section class="mm-person-result"><h3>${T('Technical Calculation Appendix','தொழில்நுட்ப கணக்கீட்டு இணைப்பு')}</h3><details class="mm-technical-evidence" data-print-technical="1"><summary>${T('Open detailed calculations','விரிவான கணக்கீடுகளைத் திறக்க')}</summary>${marriageStrengthMatrixPanel(b,g)}${renderPerson(T('Bride horoscope review','பெண் ஜாதக ஆய்வு'),bf)}${renderPerson(T('Groom horoscope review','ஆண் ஜாதக ஆய்வு'),gf)}${ku}${doshaPanel(pr,ks,sync,b,g)}${extraDoshaPanel(b,g)}${residualLagnaDoshaPanel(b,g)}${papasamyamPanel(b,g)}${numerologyPanel(b,g)}${gochar}${sand}${renderDashaDosha(sync)}${houseBasedRemedyPanel(b,g,ks)}${guidancePanel(pr,ks,sync,b,g)}</details></section>`;}

/* V216 — Long-form marriage report. Human-reading chapters are generated from the
   existing matching calculations; the core Porutham/Kuja/Dasha verdict functions remain unchanged. */
function mmV216Page(title,paras,kind='matching'){return `<article class="smv-v16-page smv-v20-rich-block mm-v16-page mm-v16-${kind}" data-smv-v16-page="1"><h4>${esc(title)}</h4>${(paras||[]).filter(Boolean).map(x=>`<p>${esc(x)}</p>`).join('')}</article>`}
function mmV216BandText(band,who){if(band==='good')return T(`${who} has usable natural support in this area; the better side of the indication becomes stronger when it is expressed consistently in behaviour.`,`${who} பக்கத்தில் இந்த அம்சத்திற்கு பயன்படுத்தக்கூடிய இயல்பான ஆதரவு உள்ளது; அந்த பலன் தினசரி நடத்தையிலும் தொடர்ந்து வெளிப்பட்டால் நல்ல பக்கம் வலுவாகும்.`);if(band==='care')return T(`${who} carries a genuine adjustment point here. This does not mean failure, but the issue is less likely to solve itself without maturity, boundaries or a deliberate routine.`,`${who} பக்கத்தில் இங்கு உண்மையான சமரச/திருத்தப் புள்ளி உள்ளது. இது தோல்வி என்று பொருள் அல்ல; முதிர்ச்சி, எல்லை அல்லது திட்டமிட்ட பழக்கம் இல்லாமல் பிரச்சினை தானாக சரியாகும் வாய்ப்பு குறைவு.`);return T(`${who} shows a mixed but workable pattern here. Good results are possible, but the outcome depends more on repeated choices than on effortless compatibility.`,`${who} பக்கத்தில் கலப்பு ஆனால் கையாளக்கூடிய pattern உள்ளது. நல்ல பலன் சாத்தியம்; ஆனால் தானாக வரும் பொருத்தத்தை விட மீண்டும் மீண்டும் செய்யும் தேர்வுகள் முடிவை அதிகம் தீர்மானிக்கும்.`)}
function mmV216IndividualTopic(c,topic,profile,who,i){const band=mmHumanBand(profile.score),style=mmHumanElementStyle(c,topic),guide=MM_HUMAN_GUIDANCE[i]||['',''];const core=band==='good'?T(topic.good[0],topic.good[1]):T(topic.care[0],topic.care[1]);return [T(`${who}: ${style}.`,`${who}: ${style}.`),mmV216BandText(band,who),core,T(guide[0],guide[1]),T('This reading is about the person’s own capacity in this area before comparing the partner. D1 gives the outer life pattern and D9 refines how marriage, values and long-term commitment mature with experience.','இந்த வாசிப்பு துணைவருடன் ஒப்பிடுவதற்கு முன் அந்த நபரின் சொந்த திறனைப் பார்க்கிறது. D1 வெளிப்புற வாழ்க்கை pattern-ஐ காட்டும்; D9 திருமணம், மதிப்புகள் மற்றும் நீண்டகால commitment அனுபவத்துடன் எப்படி முதிர்கிறது என்பதை refine செய்கிறது.')].filter(Boolean)}
function mmV216TopicPages(b,g,topic,i){const B=mmHumanTopicProfile(b,topic),G=mmHumanTopicProfile(g,topic),bs=mmHumanElementStyle(b,topic),gs=mmHumanElementStyle(g,topic),couple=mmHumanDetailedText(topic,B,G,bs,gs,i),title=T(topic.en,topic.ta),guide=MM_HUMAN_GUIDANCE[i]||['',''];return mmV216Page(`${i+1}. ${title} — ${T('Bride reading','பெண் தனி வாசிப்பு')}`,mmV216IndividualTopic(b,topic,B,T('Bride','பெண்'),i),'topic')+mmV216Page(`${i+1}. ${title} — ${T('Groom reading','ஆண் தனி வாசிப்பு')}`,mmV216IndividualTopic(g,topic,G,T('Groom','ஆண்'),i),'topic')+mmV216Page(`${i+1}. ${title} — ${T('Couple synthesis','இருவர் ஒருங்கிணைந்த வாசிப்பு')}`,[couple,T(guide[0],guide[1]),T('The practical question is not whether both people are identical, but whether the stronger side of one chart can support the weaker side of the other without control, resentment or repeated misunderstanding.','இருவரும் ஒரே மாதிரி இருக்கிறார்களா என்பது முக்கிய கேள்வி அல்ல; ஒருவரின் வலுவான பக்கம் மற்றவரின் பலவீனமான பகுதியை கட்டுப்பாடு, மனக்கசப்பு அல்லது மீண்டும் வரும் தவறான புரிதல் இல்லாமல் சமநிலைப்படுத்த முடியுமா என்பதே முக்கியம்.'),T('A demanding indication becomes more important during matching Dasha periods and when the same relationship theme is repeated in D9. A supportive indication becomes more usable when both charts and timing agree.','சவாலான சுட்டி அதே உறவு கரு D9-ல் மீண்டும் வந்து, தொடர்புடைய தசை காலமும் செயல்பட்டால் அதிக முக்கியம் பெறும். ஆதரவு சுட்டி இரு ஜாதகங்களும் காலமும் ஒத்திசைந்தால் நடைமுறையில் அதிகம் பயன்படும்.')],'topic')}
const MM239_PORUTHAM_ACTION=[["Agree on daily routines, rest and the amount of time spent together.", "அன்றாட வேலை, ஓய்வு மற்றும் இருவரும் சேர்ந்து செலவிடும் நேரம் குறித்து பேசிக் கொள்ளுங்கள்."], ["Discuss how each person reacts under pressure and how a disagreement should be paused and resumed.", "அழுத்தத்தில் ஒவ்வொருவரும் எப்படி பதிலளிக்கிறார்கள், கருத்து வேறுபாட்டில் எப்போது இடைவெளி எடுத்து மீண்டும் பேசலாம் என்பதை அறிந்துகொள்ளுங்கள்."], ["Compare long-term family aims and willingness to support each other’s development; this factor cannot determine fertility.", "நீண்டகால குடும்ப இலக்கும் ஒருவரின் வளர்ச்சிக்கு மற்றவர் தரும் ஆதரவும் பொருந்துகிறதா என்று பாருங்கள்; இது குழந்தைப்பேற்றைத் தீர்மானிக்கும் அளவுகோல் அல்ல."], ["Discuss adjustment to each family, living arrangements and the support needed after marriage.", "இரு குடும்பங்களுடன் பழகுதல், வசிக்கும் இடம் மற்றும் திருமணத்திற்குப் பிறகு தேவைப்படும் ஆதரவு குறித்து பேசுங்கள்."], ["Physical comfort depends on mutual consent, communication and respect for personal boundaries; a star classification does not establish a person’s preferences.", "உடல் நெருக்கத்தில் இருவரின் சம்மதம், உரையாடல் மற்றும் தனிப்பட்ட எல்லைக்கு மரியாதை முக்கியம்; நட்சத்திர வகை மட்டும் ஒருவரின் விருப்பத்தைத் தீர்மானிக்காது."], ["Compare how reassurance is sought, how family habits differ and how each person recovers after conflict.", "ஆறுதல் எதிர்பார்க்கும் முறை, குடும்பப் பழக்க வேறுபாடு மற்றும் கருத்து வேறுபாட்டுக்குப் பிறகு சமநிலைக்கு வரும் விதத்தைப் பேசுங்கள்."], ["Friendly sign lords are one supportive relationship between symbols; actual agreement still requires shared decisions.", "ராசி அதிபதிகளின் நட்பு ஒரு துணைச் சுட்டி; நடைமுறை ஒத்துழைப்பிற்கு இருவரும் சேர்ந்து முடிவெடுப்பது அவசியம்."], ["Attraction works best with equal influence: neither partner should have to surrender all decisions to preserve harmony.", "ஈர்ப்புடன் சம உரிமையும் இருக்க வேண்டும்; ஒற்றுமைக்காக ஒருவர் எல்லா முடிவையும் மற்றவரிடம் ஒப்படைக்க வேண்டியதில்லை."], ["Review the applicable Rajju exception before assigning weight; this flag alone cannot establish separation or a threat to life.", "பொருந்தும் ரஜ்ஜு விதிவிலக்கை முதலில் பார்க்க வேண்டும்; இந்தச் சுட்டியை மட்டும் வைத்து பிரிவு அல்லது உயிருக்கு ஆபத்து கூற முடியாது."], ["Check which birth-star pair triggered Vedha and compare it with the full relationship indicators; it is not an independent prediction of an event.", "எந்த நட்சத்திர இணைவு வேதையை ஏற்படுத்துகிறது என்பதைச் சரிபார்த்து முழு உறவுச் சுட்டிகளுடன் ஒப்பிட வேண்டும்; இது தனியான நிகழ்வுக் கணிப்பு அல்ல."]];
const MM_V216_PORUTHAM=[
['Dina / Tara','தினம் / தாரா','daily adjustment, wellbeing and the ease with which ordinary life rhythm is shared','அன்றாட ஒத்திசைவு, உடல்/மன நிம்மதி மற்றும் தினசரி வாழ்க்கை ஓட்டத்தை பகிரும் எளிமை'],
['Gana','கணம்','temperament, instinctive behaviour and how two people react when pressured','குணநிலை, இயல்பான நடத்தை மற்றும் அழுத்தத்தில் இருவரும் எப்படி எதிர்வினை செய்கிறார்கள்'],
['Mahendra','மகேந்திரம்','growth, protection and the traditional idea of continuity and mutual development','வளர்ச்சி, பாதுகாப்பு மற்றும் பரஸ்பர முன்னேற்றம்/தொடர்ச்சி பற்றிய பாரம்பரிய சுட்டி'],
['Sthree Deergha','ஸ்திரீ தீர்க்கம்','traditional wellbeing and the capacity for the bride’s life rhythm to settle into the marriage','பெண் வாழ்க்கை ஓட்டம் திருமணத்தில் நிலைபெறுதல் மற்றும் பாரம்பரிய நலச் சுட்டி'],
['Yoni','யோனி','physical instinct, attraction, private comfort and the style of intimate responsiveness','உடல் ஈர்ப்பு, இயல்பான நெருக்கம், தனிப்பட்ட வசதி மற்றும் தாம்பத்ய எதிர்வினை முறை'],
['Rasi','ராசி','Moon-sign relationship, emotional rhythm, family habit and the way daily expectations meet','சந்திர ராசி உறவு, உணர்ச்சி ஓட்டம், குடும்ப பழக்கம் மற்றும் தினசரி எதிர்பார்ப்புகள் சந்திக்கும் விதம்'],
['Rasi Lord','ராசி அதிபதி','how the two Moon-sign rulers cooperate or compete, modifying emotional compatibility','இரு சந்திர ராசி அதிபதிகள் ஒத்துழைக்கிறார்களா/மோதுகிறார்களா என்பதன் மூலம் உணர்ச்சி பொருத்தம் மாறும் விதம்'],
['Vasya','வசியம்','mutual attraction, influence, willingness to respond and the balance of give-and-take','பரஸ்பர ஈர்ப்பு, ஒருவரின் தாக்கத்திற்கு மற்றவர் பதிலளிக்கும் தன்மை மற்றும் கொடுத்தல்–பெறுதல் சமநிலை'],
['Rajju','ரஜ்ஜு','a traditional sensitive factor connected with continuity and marital stability; it requires full-chart exceptions and protection checks','திருமண தொடர்ச்சி/நிலைத்தன்மை சார்ந்த பாரம்பரிய முக்கிய சுட்டி; முழு ஜாதக விலக்கு மற்றும் பாதுகாப்பு காரணிகளுடன் மட்டுமே முடிவு செய்ய வேண்டியது'],
['Vedha','வேதை','nakshatra-level obstruction or friction; it should be weighed with stronger chart factors rather than used alone','நட்சத்திர அளவிலான தடுப்பு/உராய்வு; தனியாக தீர்ப்பு கூறாமல் வலுவான முழு ஜாதக காரணிகளுடன் சேர்த்து வாசிக்க வேண்டியது']
];
function mmV216PoruthamPages(pr){return pr.rows.map((r,i)=>{const m=MM_V216_PORUTHAM[i],a=MM239_PORUTHAM_ACTION[i];if(!m)return '';return mmV216Page(T(m[0],m[1]),[T(`This factor concerns ${m[2]}. The calculated rule ${r[1]?'is satisfied':'is not satisfied'} for this pair.`,`இந்த அம்சம் ${m[3]} தொடர்பானது. இந்த ஜோடிக்கு கணக்கிடப்பட்ட விதி ${r[1]?'பொருந்துகிறது':'பொருந்தவில்லை'}.`),r[2]?String(r[2]):'',T(a[0],a[1])],'porutham');}).join('')+mmV216Page(T('Nadi','நாடி'),[String(pr.nadi?.detail||''),pr.nadi?.ok?T('The birth stars have different Nadi categories.','ஜன்ம நட்சத்திரங்கள் வெவ்வேறு நாடி வகைகளில் உள்ளன.'):T('The birth stars share a Nadi category; the applicable traditional exceptions need review. This cannot diagnose fertility, genetics or a health condition.','ஜன்ம நட்சத்திரங்கள் ஒரே நாடி வகையில் உள்ளன; பொருந்தும் பாரம்பரிய விதிவிலக்குகளைப் பார்க்க வேண்டும். இதன் மூலம் குழந்தைப்பேறு, மரபணு அல்லது உடல்நலக் குறைபாட்டைக் கண்டறிய முடியாது.')],'porutham');}
function mmV216KujaPage(who,a,peer,c){const v=kujaVilakku(a,peer),hits=kuja(c)?.hits||[];return mmV216Page(`${who} — ${T('Kuja/Mars marriage-pressure review','செவ்வாய்/குஜ திருமண அழுத்த ஆய்வு')}`,[T(`Detected state: ${v.label||v.state}.`,`கண்டறியப்பட்ட நிலை: ${v.label||v.state}.`),hits.length?T(`Mars-sensitive reference houses in this rule set: ${hits.map(x=>x[0]+'-'+x[1]).join(', ')}. The practical meaning depends on whether the same Mars pattern is balanced in the partner chart and whether cancellation/protection is available.`,`இந்த விதியில் செவ்வாய் தாக்கம் பெறும் reference பாவங்கள்: ${hits.map(x=>x[0]+'-'+x[1]).join(', ')}. இதன் நடைமுறை அர்த்தம் மற்ற ஜாதகத்தில் ஒத்த செவ்வாய் pattern இருக்கிறதா, விலக்கு/பாதுகாப்பு கிடைக்கிறதா என்பதில் சாரும்.`):T('No major Mars-sensitive reference house is active under the current rule set.','இந்த விதியில் முக்கிய செவ்வாய்-sensitive reference பாவம் செயல்படவில்லை.'),v.reasons?.length?T(`Balancing/cancellation factors: ${v.reasons.join('; ')}.`,`விலக்கு/சமநிலை காரணிகள்: ${v.reasons.join('; ')}.`):'',T('Mars pressure is read as a tendency toward speed, sharp reaction, conflict or high demand in the connected marriage area—not as a prediction that conflict must occur. Mature conflict rules, cooling-off time and transparent decisions reduce the practical expression of the pattern.','செவ்வாய் அழுத்தம் சம்பந்தப்பட்ட திருமணப் பகுதியில் வேகம், கூர்மையான எதிர்வினை, மோதல் அல்லது அதிக கோரிக்கை tendency ஆக வாசிக்கப்படுகிறது; மோதல் கட்டாயம் நிகழும் என்று அல்ல. mature conflict rules, cooling-off நேரம் மற்றும் வெளிப்படையான முடிவு அதன் நடைமுறை வெளிப்பாட்டை குறைக்க உதவும்.')],'dosha')}
function mmV216NodePage(who,c,syncSide){const r=rahuVilakku(syncSide),k=kalaSarpaAssessment(c),n=nagaDoshaAssessment(c);return mmV216Page(`${who} — ${T('Rahu/Ketu marriage-axis reading','ராகு/கேது திருமண அச்சு வாசிப்பு')}`,[r.label||r.text,r.reasons?.length?T(`Protection/context: ${r.reasons.join('; ')}.`,`பாதுகாப்பு/சூழல்: ${r.reasons.join('; ')}.`):'',T('A nodal marriage-axis pattern is interpreted as intensity, unusual expectations, secrecy/confusion risk, rapid shifts or periods of withdrawal depending on the actual node and house involved. It becomes more relevant in Rahu/Ketu periods and when D9 repeats the same relationship issue.','node திருமண அச்சு intensity, வழக்கத்திற்கு மாறான எதிர்பார்ப்பு, மறைவு/குழப்பம், திடீர் திசைமாற்றம் அல்லது விலகல் tendency ஆக சம்பந்தப்பட்ட node/பாவத்திற்கேற்ப வாசிக்கப்படுகிறது. ராகு/கேது தசை காலங்களிலும் D9 அதே உறவு விஷயத்தை மீண்டும் காட்டும்போதும் இது அதிக முக்கியம் பெறும்.'),T(`Kala Sarpa: ${k.text}`,`கால சர்ப்பம்: ${k.text}`),T(`Naga/Sarpa tradition-based check: ${n.label}. ${n.text}`,`நாக/சர்ப்ப மரபு ஆய்வு: ${n.label}. ${n.text}`)],'dosha')}
function mmV254NagaConclusion(n){
 if(n.state==='unknown')return n.label;
 if(n.state==='none')return T('The initial indicators do not reach this rule set’s significance threshold. This is different from a detected condition being reduced by protection.','ஆரம்பக் குறிகள் இந்த விதித்தொகுப்பின் குறிப்பிடத்தக்க வரம்பை எட்டவில்லை. தோஷக் குறிகள் உருவாகி பிறகு ஆதரவால் குறைவது என்பது இதிலிருந்து வேறுபட்ட நிலை.');
 if(n.state==='balanced')return T('Indicators were detected initially, but the available protection equals or exceeds their weight. Nothing remains in this weighted residual calculation. This does not mean the two partners have equal dosha, or that every other chart factor is favourable.','முதலில் குறிகள் கண்டறியப்பட்டன; அவற்றின் மதிப்பிற்கு சமமாகவோ அதிகமாகவோ ஆதரவு கிடைத்ததால் இந்தக் கணக்கில் மீதமுள்ள மதிப்பு பூஜ்ஜியம். இதனால் இருவருக்கும் சமமான தோஷம் உள்ளது என்றோ மற்ற எல்லாப் பொருத்தங்களும் சாதகம் என்றோ அர்த்தமில்லை.');
 return T(`After subtracting the available protection, ${n.net} points remain. The final category is ${n.state==='mild'?'low':n.state==='active'?'moderate':'strong'} residual influence under these rules. A protection factor reduces the weight; it does not automatically erase the original placement.`,`கிடைக்கும் ஆதரவை கழித்த பிறகு ${n.net} மதிப்பு மீதமுள்ளது. இந்த விதிகளின்படி இறுதி நிலை ${n.state==='mild'?'குறைந்த':n.state==='active'?'மிதமான':'வலுவான'} மீதத் தாக்கம். ஆதரவு இருப்பது அதன் மதிப்பைக் குறைக்கும்; ஆரம்ப கிரக அமைப்பு இல்லாததாக மாறிவிட்டது என்று பொருள் இல்லை.`);
}
function mmV216NagaPage(who,c){
 const n=nagaDoshaAssessment(c),areaMap={putra:T('children and family planning','குழந்தைகள் மற்றும் குடும்பத் திட்டம்'),marriage:T('partnership and expectations','துணை உறவு மற்றும் எதிர்பார்ப்புகள்'),family:T('family and shared responsibilities','குடும்பம் மற்றும் கூட்டு பொறுப்புகள்'),mind:T('emotional response and peace of mind','உணர்ச்சி வெளிப்பாடு மற்றும் மனஅமைதி')};
 if(n.state==='unknown')return mmV216Page(who+' — '+T('Naga/Sarpa review','நாக/சர்ப்ப ஆய்வு'),[n.label,n.text],'dosha');
 const result=mmV216Page(who+' — '+T('Naga/Sarpa: final result and reasons','நாக/சர்ப்பம்: இறுதி நிலையும் காரணங்களும்'),[n.label,mmV254NagaConclusion(n)],'dosha');
 const table=`<table class="mm-v254-naga-weights"><thead><tr><th>${T('Step','கணக்கின் பகுதி')}</th><th>${T('Value','மதிப்பு')}</th><th>${T('Meaning','பொருள்')}</th></tr></thead><tbody><tr><td>${T('Initial indicators','ஆரம்பக் குறிகள்')}</td><td>${n.raw}</td><td>${T('Weight assigned to the detected placements and associations.','கண்டறியப்பட்ட கிரக நிலை மற்றும் தொடர்புகளுக்கு வழங்கிய எடை.')}</td></tr><tr><td>${T('Protective support','குறைக்கும் ஆதரவு')}</td><td>${n.protect}</td><td>${T('Weight from the supported 5th lord, Jupiter and available D7 checks.','5-ஆம் அதிபதி, குரு மற்றும் கிடைக்கும் D7 ஆதரவிற்கு வழங்கிய எடை.')}</td></tr><tr><td>${T('Remaining influence','மீதமுள்ள மதிப்பு')}</td><td>${n.net}</td><td>${T('Initial weight minus protection, with a minimum of zero.','ஆரம்ப மதிப்பில் ஆதரவை கழித்த மதிப்பு; பூஜ்ஜியத்திற்கு கீழ் எடுத்துக்கொள்ளப்படாது.')}</td></tr></tbody></table>`;
 const reasons=n.hits.length?`<h4>${T('Why the initial indicators appeared','ஆரம்பக் குறிகள் வந்த காரணங்கள்')}</h4><ul>${n.hits.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>`:'';
 const relief=`<h4>${T('What reduces the result','தாக்கத்தை குறைக்கும் காரணங்கள்')}</h4>${n.relief.length?'<ul>'+n.relief.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>'+T('No protective weight was added by the available checks. This is not a claim that the entire chart lacks support.','கிடைத்த இந்தச் சோதனைகளில் குறைக்கும் ஆதரவு மதிப்பு சேர்க்கப்படவில்லை. முழு ஜாதகத்திலும் ஆதரவு இல்லை என்று இதனால் கூறப்படவில்லை.')+'</p>'}`;
 const context=mmV216Page(T('How to apply this result','இந்த முடிவை எப்படிப் புரிந்துகொள்வது'),[
 T('These are internal comparison weights, not a percentage, medical risk or probability of an event. Low residual means 1–2 points; moderate means 3–5; strong means 6 or more. Zero residual after a significant initial trigger is shown separately.','இவை ஒப்பீட்டிற்கான உள் மதிப்பீட்டு எடைகள்; சதவீதமோ மருத்துவ அபாயமோ ஒரு நிகழ்வின் நிகழ்தகவோ அல்ல. மீதி 1–2 என்றால் குறைந்த தாக்கம்; 3–5 என்றால் மிதமான தாக்கம்; 6 அல்லது அதற்கு மேல் என்றால் வலுவான தாக்கம். குறிப்பிடத்தக்க ஆரம்பக் குறிகள் இருந்து மீதி 0 வந்த நிலை தனியாகக் காட்டப்படுகிறது.'),
 n.areas.length?T('The closest contextual review concerns '+n.areas.map(x=>areaMap[x]).filter(Boolean).join(', ')+'.','இங்கு நெருக்கமாகப் பார்க்க வேண்டிய வாழ்க்கைப் பகுதிகள்: '+n.areas.map(x=>areaMap[x]).filter(Boolean).join(', ')+'.'):'',
 T('Individual protection and balance between partners answer different questions. First read each person’s residual result; then compare the two. One person’s stronger score is not cancelled merely because the other person has a lower score.','தனி ஜாதகத்தில் தாக்கம் குறைவதும் இருவருக்கிடையே தோஷ அளவு ஒத்திருக்கிறதா என்பதும் வெவ்வேறு கேள்விகள். முதலில் ஒவ்வொருவரின் மீதமுள்ள நிலையைப் பார்த்து, பிறகு இரண்டையும் ஒப்பிட வேண்டும். ஒருவரின் மதிப்பு குறைவாக இருப்பதால் மற்றவரின் அதிக மதிப்பு தானாக நீங்காது.'),
 T('Naga/Sarpa and Kala Sarpa are separate checks. This result alone does not establish infertility, a partner’s health or the success of a marriage.','நாக/சர்ப்ப ஆய்வும் கால சர்ப்ப ஆய்வும் தனித்தனியானவை. இந்த ஒரு முடிவால் குழந்தைப்பேறு, துணைவரின் உடல்நிலை அல்லது திருமண வாழ்க்கையின் முடிவை உறுதி செய்ய முடியாது.')],'dosha');
 return result+table+reasons+relief+context;
}
function mmV216DoshaPages(b,g,pr,ks,ds,sync,v){const nb=nagaDoshaAssessment(b),ng=nagaDoshaAssessment(g),bk=kalaSarpaAssessment(b),gk=kalaSarpaAssessment(g),nv=nadiVilakku(pr,b,g),rj=rajjuVilakku(pr),sev=syncSeverity(sync);let html='';html+=mmV216KujaPage(T('Bride','பெண்'),ks.B,ks.G,b);html+=mmV216KujaPage(T('Groom','ஆண்'),ks.G,ks.B,g);html+=mmV216NodePage(T('Bride','பெண்'),b,sync.br);html+=mmV216NodePage(T('Groom','ஆண்'),g,sync.gr);html+=mmV216Page(`${T('Bride Kala Sarpa — detailed context','பெண் கால சர்ப்பம் — விரிவான சூழல்')}`,[bk.text,T('Kala Sarpa is judged separately from Naga/Sarpa and from ordinary Rahu/Ketu house placement. Even when present, the node-house focus, node-sign lords, close associations and the rest of the horoscope decide how strongly it operates.','கால சர்ப்பம் நாக/சர்ப்ப ஆய்விலிருந்தும் சாதாரண ராகு/கேது பாவ நிலையிலிருந்தும் தனியாக கணிக்கப்படுகிறது. இருந்தாலும் node house focus, node-sign lords, நெருக்கமான சேர்க்கைகள் மற்றும் முழு ஜாதகமே அதன் செயல்தீவிரத்தை தீர்மானிக்கும்.')],'dosha');html+=mmV216Page(`${T('Groom Kala Sarpa — detailed context','ஆண் கால சர்ப்பம் — விரிவான சூழல்')}`,[gk.text,T('It is a whole-chart modifier, not an automatic marriage veto. The report therefore carries it into Dasha timing and relationship behaviour rather than using it as a stand-alone rejection rule.','இது முழு ஜாதகத்தை மாற்றி வாசிக்க வேண்டிய modifier; தானாக திருமண நிராகரிப்பு அல்ல. அதனால் தனி rejection rule ஆக அல்லாமல் தசை timing மற்றும் உறவு நடத்தையுடன் இணைக்கப்படுகிறது.')],'dosha');html+=mmV216Page(`${T('Naga/Sarpa Dosha — method, scope and distinction','நாக/சர்ப்ப தோஷம் — முறை, வரம்பு மற்றும் வேறுபாடு')}`,[T('Naga/Sarpa Dosha is not treated here as a synonym for Kala Sarpa. Published South-Indian practices differ: some emphasise Rahu/Ketu in marriage- and family-sensitive houses from Lagna or Moon, while other practitioners give greater weight to the 5th house, 5th lord, Jupiter and D7 because of progeny significance.','நாக/சர்ப்ப தோஷம் இங்கு கால சர்ப்பத்தின் வேறு பெயராக எடுத்துக்கொள்ளப்படவில்லை. வெளியிடப்பட்ட தென்னிந்திய நடைமுறைகளில் விதிகள் மாறுகின்றன: சிலர் லக்னம்/சந்திரனிலிருந்து திருமணம்–குடும்ப sensitive பாவங்களில் ராகு/கேதுவை பார்க்கிறார்கள்; சிலர் புத்திரக் காரணத்தால் 5-ஆம் பாவம், 5-ஆம் அதிபதி, குரு மற்றும் D7-க்கு அதிக எடை தருகிறார்கள்.'),T('Therefore the engine uses a transparent weighted review and separately shows protection from a strong 5th lord, Jupiter and D7. A mild flag is not promoted into a severe dosha merely to create a label.','அதனால் engine வெளிப்படையான weighted review பயன்படுத்தி, வலுவான 5-ஆம் அதிபதி, குரு மற்றும் D7 தரும் பாதுகாப்பையும் தனியாகக் காட்டுகிறது. பெயர் உருவாக்குவதற்காக மிதமான flag-ஐ வலுவான தோஷமாக உயர்த்தாது.'),T('This is a tradition-based interpretive layer, not a medical diagnosis or a scientifically established causal rule. Fertility concerns must be handled medically.','இது மரபு சார்ந்த ஜோதிட interpretation layer; மருத்துவ diagnosis அல்லது அறிவியல் காரண விதி அல்ல. கருத்தரிப்பு தொடர்பான கவலைகள் மருத்துவ முறையிலேயே கையாளப்பட வேண்டும்.')],'dosha');html+=mmV216NagaPage(T('Bride','பெண்'),b);html+=mmV216NagaPage(T('Groom','ஆண்'),g);html+=mmV216Page(`${T('Naga/Sarpa couple balance — how to read the pair','நாக/சர்ப்ப இருவர் சமநிலை — ஜோடியை எப்படி வாசிக்க வேண்டும்')}`,[T(`Bride: ${nb.label}. Groom: ${ng.label}.`,`பெண்: ${nb.label}. ஆண்: ${ng.label}.`),T('If both charts carry comparable nodal sensitivity, the question becomes whether their protection factors, D7/D9 strength and Dasha timing are also comparable. If only one chart is strongly affected, that asymmetry receives more attention in counselling and timing.','இரு ஜாதகங்களிலும் ஒப்பிடத்தக்க node sensitivity இருந்தால், பாதுகாப்பு காரணிகள், D7/D9 பலம் மற்றும் தசை timing-மும் ஒப்பிடத்தக்கதா என்பதே அடுத்த கேள்வி. ஒரே ஜாதகத்தில் மட்டும் வலுவான பாதிப்பு இருந்தால் அந்த சமமின்மை ஆலோசனை மற்றும் கால ஆய்வில் அதிக கவனம் பெறும்.'),T('Naga/Sarpa is never used as a stand-alone marriage rejection in this report. Repeated evidence across family/progeny houses, relationship houses, karakas and active periods matters more than one placement.','இந்த report-ல் நாக/சர்ப்பம் தனியாக திருமண நிராகரிப்பு காரணமாக பயன்படுத்தப்படாது. குடும்ப/புத்திர பாவங்கள், உறவு பாவங்கள், காரகர்கள் மற்றும் செயலில் உள்ள காலங்களில் ஒரே சுட்டி மீண்டும் வருகிறதா என்பதே ஒரு தனி placement-ஐ விட முக்கியம்.')],'dosha');html+=mmV216Page(`${T('Nadi — residual risk and protection','நாடி — மீதமுள்ள நிலை மற்றும் பாதுகாப்பு')}`,[nv.label||nv.text,nv.reasons?.length?T(`Exception/protection factors: ${nv.reasons.join('; ')}.`,`விதிவிலக்கு/பாதுகாப்பு காரணிகள்: ${nv.reasons.join('; ')}.`):'',T('Nadi is important in traditional matching, but the report does not allow it to erase strong D1/D9, 7th-house, Jupiter/Venus or progeny support without checking the wider context.','பாரம்பரிய பொருத்தத்தில் நாடி முக்கியம்; ஆனால் D1/D9, 7-ஆம் பாவம், குரு/சுக்கிரன் அல்லது புத்திர ஆதரவை முழு சூழல் பார்க்காமல் நாடி மட்டும் அழித்துவிட அனுமதிக்கப்படாது.')],'dosha');html+=mmV216Page(`${T('Rajju — continuity and stability review','ரஜ்ஜு — தொடர்ச்சி மற்றும் நிலைத்தன்மை ஆய்வு')}`,[rj.label||rj.text,rj.reasons?.length?T(`Exception/protection factors: ${rj.reasons.join('; ')}.`,`விதிவிலக்கு/பாதுகாப்பு காரணிகள்: ${rj.reasons.join('; ')}.`):'',T('Rajju is treated as a sensitive traditional factor. The final judgement asks whether the individual marriage promise, dosha balance and timing provide enough protection rather than treating the star rule as a mechanical verdict.','ரஜ்ஜு sensitive traditional factor ஆகப் பார்க்கப்படுகிறது. நட்சத்திர விதியை mechanical verdict ஆக மாற்றாமல், இரு ஜாதகங்களின் திருமண வாக்குறுதி, தோஷ சமநிலை மற்றும் காலம் போதுமான பாதுகாப்பு தருகிறதா என்பதே இறுதி கேள்வி.')],'dosha');html+=mmV216Page(`${T('Dasha-Dosha synchronisation — combined judgement','தசா–தோஷ ஒத்திசைவு — ஒருங்கிணைந்த முடிவு')}`,[T(`Mars synchronisation flag: ${sev.status?.Mars?.overlap?'overlap':sev.status?.Mars?.near?'near':'not significant'}; Rahu synchronisation flag: ${sev.status?.Rahu?.overlap?'overlap':sev.status?.Rahu?.near?'near':'not significant'}.`,`செவ்வாய் ஒத்திசைவு: ${sev.status?.Mars?.overlap?'ஒரே காலம்':sev.status?.Mars?.near?'அருகாமை':'முக்கியமில்லை'}; ராகு ஒத்திசைவு: ${sev.status?.Rahu?.overlap?'ஒரே காலம்':sev.status?.Rahu?.near?'அருகாமை':'முக்கியமில்லை'}.`),T('A difficult planet period does not manufacture a dosha. The timing becomes important only when that same dosha remains unresolved in the natal chart; otherwise the period is read through the planet’s ordinary relationship/life significations.','கடின கிரக தசை புதிய தோஷத்தை உருவாக்காது. பிறப்பு ஜாதகத்தில் அதே தோஷம் விலக்கு பெறாமல் மீதமிருந்தால் மட்டுமே timing risk அதிகரிக்கும்; இல்லையெனில் அந்த கிரகத்தின் சாதாரண உறவு/வாழ்க்கை காரகத்துவம் மூலமே காலம் வாசிக்கப்படும்.'),ds.length?T(`The closest Mahadasha-ending pair in the available range is about ${ds[0].days} days apart. This is a transition-review flag, not an automatic separation indicator.`,`கிடைக்கும் காலவரம்பில் மிக அருகிலுள்ள மகாதசை முடிவு சுமார் ${ds[0].days} நாட்கள் இடைவெளியில் உள்ளது. இது transition ஆய்வு flag; தானாக பிரிவு சுட்டி அல்ல.`):T('No close Mahadasha-ending pair was found in the available range.','கிடைக்கும் காலவரம்பில் அருகிலுள்ள மகாதசை முடிவு ஜோடி இல்லை.')],'dosha');html+=mmV220FunctionalDoshaPages(b,g,pr);html+=mmV216Page(`${T('Overall dosha synthesis','மொத்த தோஷ ஒருங்கிணைவு')}`,[T(`Final matching status: ${v.label||v.status||''}.`,`இறுதி பொருத்த நிலை: ${v.label||v.status||''}.`),T(`Bride Naga/Sarpa: ${nb.label}; Groom Naga/Sarpa: ${ng.label}. Bride Kala Sarpa: ${bk.present?'present':'not formed'}; Groom Kala Sarpa: ${gk.present?'present':'not formed'}.`,`பெண் நாக/சர்ப்பம்: ${nb.label}; ஆண் நாக/சர்ப்பம்: ${ng.label}. பெண் கால சர்ப்பம்: ${bk.present?'உள்ளது':'இல்லை'}; ஆண் கால சர்ப்பம்: ${gk.present?'உள்ளது':'இல்லை'}.`),T('The purpose of this synthesis is to identify what needs maturity, timing or protection—not to multiply fear by counting every dosha label. Repeated indications matter more than isolated labels.','இந்த ஒருங்கிணைப்பின் நோக்கம் ஒவ்வொரு தோஷப் பெயரையும் எண்ணி பயம் அதிகரிப்பது அல்ல; எங்கு முதிர்ச்சி, நேரத் தேர்வு அல்லது பாதுகாப்பு தேவை என்பதைக் கண்டறிதல். தனித்தனி பெயர்களை விட மீண்டும் வரும் ஒரே சுட்டிகள் அதிக முக்கியம்.')],'dosha');return html}
function mmV216YearSignals(c,start,end,ctx){return mmDashaTimeline(c,start,end).filter(x=>x.level==='AD').map(x=>mmMarriagePeriodSignal(c,x,ctx))}
function mmV216YearPage(year,b,g,bc,gc){const ys=new Date(Date.UTC(year,0,1)),ye=new Date(Date.UTC(year,11,31)),bw=mmV216YearSignals(b,ys,ye,bc).sort((a,b)=>b.relevance-a.relevance),gw=mmV216YearSignals(g,ys,ye,gc).sort((a,b)=>b.relevance-a.relevance),B=bw[0],G=gw[0],ov=B&&G?mmOverlapPeriod(B,G):null,combined=(B?.balance||0)+(G?.balance||0);const flow=combined>=2?T('The year leans more supportive for relationship decisions when real-life readiness also exists.','நடைமுறை தயாரிப்பும் இருந்தால் இந்த ஆண்டு உறவு முடிவுகளுக்கு ஆதரவு அதிகமாக இருக்கலாம்.'):combined<=-2?T('The year asks for more adjustment, patience and correction before irreversible relationship decisions.','திரும்ப முடியாத உறவு முடிவுகளுக்கு முன் அதிக சமரசம், பொறுமை மற்றும் திருத்தம் கேட்கும் ஆண்டு.'):T('The year is mixed: some periods support progress while others ask the couple to slow down and review expectations.','இந்த ஆண்டு கலப்பு: சில காலங்கள் முன்னேற்றத்தையும் சில காலங்கள் எதிர்பார்ப்புகளை மெதுவாக மறுபரிசீலிக்கவும் கேட்கும்.');return mmV216Page(`${year} — ${T('Marriage / relationship timing reading','திருமணம் / உறவு கால வாசிப்பு')}`,[B?T(`Bride: ${B.label} (${B.start} → ${B.end}) — ${B.signalLabel}. ${B.why.slice(0,2).join(' ')}`,`பெண்: ${B.label} (${B.start} → ${B.end}) — ${B.signalLabel}. ${B.why.slice(0,2).join(' ')}`):T('Bride: no unusually strong relationship Bhukti selected for this calendar year.','பெண்: இந்த ஆண்டில் தனி வலுவான உறவு புக்தி தேர்வு செய்யப்படவில்லை.'),G?T(`Groom: ${G.label} (${G.start} → ${G.end}) — ${G.signalLabel}. ${G.why.slice(0,2).join(' ')}`,`ஆண்: ${G.label} (${G.start} → ${G.end}) — ${G.signalLabel}. ${G.why.slice(0,2).join(' ')}`):T('Groom: no unusually strong relationship Bhukti selected for this calendar year.','ஆண்: இந்த ஆண்டில் தனி வலுவான உறவு புக்தி தேர்வு செய்யப்படவில்லை.'),ov?T(`The two periods overlap from ${mmIsoDate(ov[0])} to ${mmIsoDate(ov[1])}. This makes the year more relevant for shared decisions, but the natal promise and unresolved doshas still decide the quality of the result.`,`இருவரின் காலமும் ${mmIsoDate(ov[0])} முதல் ${mmIsoDate(ov[1])} வரை overlap ஆகிறது. இதனால் கூட்டு முடிவுகளுக்கு ஆண்டு முக்கியமாகிறது; ஆனால் பலனின் தரத்தை பிறப்பு வாக்குறுதியும் மீதமுள்ள தோஷங்களும் தீர்மானிக்கும்.`):T('There is no major selected overlap in the strongest Bhukti windows; the couple may experience the year differently and should not force identical timing.','தேர்வு செய்யப்பட்ட வலுவான புக்திகளில் முக்கிய overlap இல்லை; இருவரும் ஆண்டை வேறு விதமாக அனுபவிக்கலாம், ஒரே timing-ஐ force செய்ய வேண்டாம்.'),flow,T('For an unmarried couple, a supportive year is a candidate for introduction, family discussion, engagement or marriage only when real-world readiness exists. For an already married couple, the same astrology can describe commitment, home, finances, intimacy or family expansion rather than a new marriage.','திருமணம் ஆகாதவர்களுக்கு supportive year என்பது real-life readiness இருந்தால் அறிமுகம், குடும்ப பேச்சு, நிச்சயம் அல்லது திருமண candidate ஆகலாம். ஏற்கனவே திருமணமானவர்களுக்கு அதே காலம் புதிய திருமணம் அல்ல; commitment, வீடு, நிதி, நெருக்கம் அல்லது குடும்ப விரிவு ஆக வெளிப்படலாம்.')],'timing')}
function mmV216TimingPages(b,g,ks,sync){const start=mmAnalysisDate(),kb=kujaVilakku(ks.B,ks.G),kg=kujaVilakku(ks.G,ks.B),rb=rahuVilakku(sync.br),rg=rahuVilakku(sync.gr),bc=mmTimelineContext(b,kb,rb),gc=mmTimelineContext(g,kg,rg),y0=start.getUTCFullYear();let html='';for(let i=0;i<15;i++)html+=mmV216YearPage(y0+i,b,g,bc,gc);return html}
function mmV216RemedyPages(b,g,pr,ks,sync){const nb=nagaDoshaAssessment(b),ng=nagaDoshaAssessment(g),activeNaga=['mild','active','strong'].includes(nb.state)||['mild','active','strong'].includes(ng.state),kb=kujaVilakku(ks.B,ks.G),kg=kujaVilakku(ks.G,ks.B),activeKuja=['partial','active','strong','consult'].includes(kb.state)||['partial','active','strong','consult'].includes(kg.state),rb=rahuVilakku(sync.br),rg=rahuVilakku(sync.gr),activeNode=['active','complex'].includes(rb.state)||['active','complex'].includes(rg.state)||kalaSarpaAssessment(b).present||kalaSarpaAssessment(g).present;let html='';html+=mmV216Page(T('Remedy 1 — lifestyle and relationship discipline','பரிகாரம் 1 — வாழ்வியல் மற்றும் உறவு ஒழுங்கு'),[T('The first remedy is behavioural: one fixed weekly conversation for money, family expectations, work pressure and major decisions; no major decision during anger; clear privacy and family boundaries; written clarity for debt/property.','முதல் பரிகாரம் வாழ்வியல்: பணம், குடும்ப எதிர்பார்ப்பு, வேலை அழுத்தம் மற்றும் பெரிய முடிவுகளுக்கு வாரத்திற்கு ஒரு நிரந்தர உரையாடல்; கோபத்தில் பெரிய முடிவு வேண்டாம்; தனியுரிமை/குடும்ப எல்லை தெளிவு; கடன்/சொத்துக்கு எழுதப்பட்ட தெளிவு.'),T('This is the part of remedy that directly changes repeated behaviour. Devotional practice is supportive, but it should not be used to avoid practical correction.','மீண்டும் வரும் நடத்தையை நேரடியாக மாற்றுவது இந்த வாழ்வியல் பரிகாரமே. பக்தி நடைமுறை துணை; நடைமுறை திருத்தத்தை தவிர்க்கும் மாற்று அல்ல.')],'remedy');html+=mmV216Page(T('Remedy 2 — Mars/Kuja pattern','பரிகாரம் 2 — செவ்வாய்/குஜ pattern'),activeKuja?[T('When residual Kuja pressure remains, use a cooling-off rule, physical discipline/exercise, shared decision rules and no threatening language during conflict.','மீதமுள்ள குஜ அழுத்தம் இருந்தால் cooling-off rule, உடற்பயிற்சி/ஒழுக்கம், கூட்டு முடிவு விதிகள் மற்றும் மோதலில் அச்சுறுத்தும் பேச்சை தவிர்க்கவும்.'),T('Traditional option according to family practice: Tuesday Murugan/Subrahmanya or Angaraka/Navagraha worship, charity/service and disciplined conduct.','குடும்ப மரபுப்படி பாரம்பரிய வழி: செவ்வாய்க்கிழமை முருகன்/சுப்பிரமணியர் அல்லது அங்காரக/நவகிரக வழிபாடு, தானம்/சேவை மற்றும் ஒழுக்கமான நடத்தை.')]:[T('No strong residual Kuja pattern requires a special Mars remedy. General conflict-management discipline is enough.','வலுவான மீதமுள்ள குஜ pattern இல்லை; பொதுவான conflict-management ஒழுங்கே போதும்.')],'remedy');html+=mmV216Page(T('Remedy 3 — Rahu/Ketu, Kala Sarpa and Naga/Sarpa','பரிகாரம் 3 — ராகு/கேது, கால சர்ப்பம் மற்றும் நாக/சர்ப்பம்'),activeNode||activeNaga?[T('For nodal patterns, the practical remedy is clarity: avoid secrecy, verify facts, reduce fear-based interpretation, and do not make sudden relationship decisions during intense periods.','node pattern-களில் நடைமுறை பரிகாரம் தெளிவு: மறைவைத் தவிர்க்கவும், உண்மைகளை சரிபார்க்கவும், பயம் சார்ந்த விளக்கத்தை குறைக்கவும், தீவிர காலத்தில் திடீர் உறவு முடிவு எடுக்க வேண்டாம்.'),T('Traditional options may include Ganesha, Durga, Subrahmanya/Murugan or Navagraha worship according to family tradition. For an active Naga/Sarpa tradition-based pattern, Ayilyam/Ashlesha or Naga Panchami observance and established temple rites may be considered only when a trusted family/temple priest advises them.','குடும்ப மரபுப்படி விநாயகர், துர்கை, சுப்பிரமணியர்/முருகன் அல்லது நவகிரக வழிபாடு செய்யலாம். செயலில் உள்ள நாக/சர்ப்ப மரபு pattern-க்கு ஆயில்யம்/ஆஸ்லேஷா அல்லது நாக பஞ்சமி வழிபாடு மற்றும் நிலையான கோயில் முறைகள் நம்பகமான குடும்ப/கோயில் புரோகிதர் அறிவுறுத்தினால் மட்டும் செய்யலாம்.')]:[T('No strong residual nodal/Naga pattern requires a dedicated ritual plan; general devotional practice may be followed without fear.','வலுவான node/Naga மீதமுள்ள pattern இல்லை; பயமின்றி பொதுவான பக்தி வழியை பின்பற்றலாம்.')],'remedy');html+=mmV216Page(T('Remedy 4 — marriage harmony and family expansion','பரிகாரம் 4 — திருமண ஒற்றுமை மற்றும் குடும்ப விரிவு'),[T('For marriage harmony, strengthen consent, affection, shared financial planning, family boundaries and fair responsibility. When repeated conflict persists, relationship counselling is a practical remedy rather than a failure.','திருமண ஒற்றுமைக்கு சம்மதம், அன்பு, கூட்டு நிதித் திட்டம், குடும்ப எல்லைகள் மற்றும் நியாயமான பொறுப்பு பகிர்வை வலுப்படுத்துங்கள். மோதல் தொடர்ந்து இருந்தால் relationship counselling தோல்வி அல்ல; நடைமுறை பரிகாரம்.'),T('For fertility/children concerns, medical care remains primary. Jupiter/D7 and Naga/Sarpa indications can be used for traditional timing or devotional context, not as medical diagnosis.','கருத்தரிப்பு/குழந்தை கவலைகளில் மருத்துவ பராமரிப்பே முதன்மை. குரு/D7 மற்றும் நாக/சர்ப்ப சுட்டிகளை பாரம்பரிய timing அல்லது பக்தி சூழலுக்கே பயன்படுத்த வேண்டும்; medical diagnosis ஆக அல்ல.')],'remedy');html+=mmV216Page(T('Remedy 5 — what not to prescribe automatically','பரிகாரம் 5 — தானாக பரிந்துரைக்கக்கூடாதவை'),[T('Do not prescribe a gemstone merely because a planet appears weak or afflicted. A gemstone strengthens the planet, so house ownership and the whole chart must be judged first.','ஒரு கிரகம் பலம் குறைவு/பாதிப்பு என்று மட்டும் ரத்தினம் பரிந்துரைக்க வேண்டாம். ரத்தினம் அந்த கிரகத்தை வலுப்படுத்துவதால் பாவ அதிபத்தியமும் முழு ஜாதகமும் முதலில் பார்க்க வேண்டும்.'),T('Avoid expensive fear-based “dosha removal” guarantees. Traditional worship can support discipline and devotion, but medical, legal, fertility, financial and mental-health concerns belong with qualified professionals.','பயம் உருவாக்கும் விலையுயர்ந்த “தோஷ நீக்கம்” உறுதிகளைத் தவிர்க்கவும். பாரம்பரிய வழிபாடு ஒழுக்கம்/பக்திக்கு துணை; மருத்துவம், சட்டம், கருத்தரிப்பு, நிதி, மனநல பிரச்சினைகள் தகுதியான நிபுணர்களுக்குரியது.')],'remedy');return html}
function marriageV216LongForm(b,g,pr,ks,ds,sync,v){const html=mmV216PoruthamPages(pr)+mmV216DoshaPages(b,g,pr,ks,ds,sync,v)+mmV216RemedyPages(b,g,pr,ks,sync);return `<details class="mm-v16-longform"><summary><b>${T('Detailed Porutham, dosha and remedy review','விரிவான பொருத்தம், தோஷம் மற்றும் பரிகார ஆய்வு')}</b></summary>${html}</details>`;}



/* V220 matching refinements: Shashtashtaka and Kendradhipatya are shown as
   transparent secondary checks, not as automatic marriage vetoes. */
function mmOwnedHouses(c,pn){const lag=Number(c?.lagna?.longitude);if(!Number.isFinite(lag))return[];const out=[];for(let signIdx=0;signIdx<12;signIdx++)if(LORD[signIdx]===pn)out.push(house(signIdx*30+1,lag));return out.sort((a,b)=>a-b)}
function mmKendraAdhipatya(c){const hits=[];for(const pn of [P.Jupiter,P.Venus,P.Mercury,P.Moon]){const owned=mmOwnedHouses(c,pn),k=owned.filter(h=>[4,7,10].includes(h)),tri=owned.filter(h=>[1,5,9].includes(h));if(k.length&&!tri.length){const p=planet(c,pn);hits.push({planet:pn,owned,k,str:p?dignity(pn,p.longitude):'—'});}}return {present:hits.length>0,hits,label:hits.length?T('Present as a functional-lord refinement','உள்ளது — functional-lord refinement'):T('Not prominent','முக்கியமாக இல்லை')}}
function mmShashtashtaka(pr){const r=pr?.rasi||{},present=!!r.shashtashtaka,mitigated=present&&!!r.lordFriendly;return {present,mitigated,text:!present?T('Not present','இல்லை'):mitigated?T('Present — Moon-sign lords are friendly/same-lord, so the 6/8 flag is moderated','உள்ளது — சந்திர ராசி அதிபதிகள் நட்பு/ஒத்த அதிபதி என்பதால் 6/8 குறி மிதமாக்கப்படுகிறது'):T('Present — 6/8 Moon-sign relationship; full-chart adjustment review required','உள்ளது — 6/8 சந்திர ராசி உறவு; முழு ஜாதக ஒத்திசைவு ஆய்வு தேவை')}}
function mmV220FunctionalDoshaPages(b,g,pr){const bk=mmKendraAdhipatya(b),gk=mmKendraAdhipatya(g),sh=mmShashtashtaka(pr),fmt=x=>x.hits.length?x.hits.map(z=>`${T(z.planet==='குரு'?'Jupiter':z.planet==='சுக்கிரன்'?'Venus':z.planet==='புதன்'?'Mercury':'Moon',z.planet)} — ${T('houses','பாவங்கள்')} ${z.owned.join(', ')} · ${z.str}`).join('; '):T('No prominent condition','முக்கிய குறி இல்லை');let html='';html+=mmV216Page(T('Shashtashtaka / 6–8 Moon-sign relationship — detailed reading','ஷஷ்டாஷ்டக / 6–8 சந்திர ராசி உறவு — விரிவான வாசிப்பு'),[sh.text,T('This factor belongs to the Rasi/Bhakoot layer. If it is present, the practical themes are adjustment, health/routine differences, money/expense handling and the pace of emotional adaptation. It is read together with Moon strength, Rasi-lord friendship, 7th house/D9 and the Dasha timing rather than used alone.','இந்த காரணி ராசி/Bhakoot அடுக்கைச் சேர்ந்தது. இருந்தால் நடைமுறையில் ஒத்திசைவு, உடல்நல/தினசரி பழக்க வேறுபாடு, பணம்–செலவு கையாளுதல் மற்றும் உணர்ச்சி ஏற்பின் வேகம் ஆகியவற்றில் அதிக கவனம் தேவைப்படலாம். சந்திர பலம், ராசி அதிபதி நட்பு, 7-ஆம் பாவம்/D9 மற்றும் தசை காலத்துடன் சேர்த்தே வாசிக்க வேண்டும்.'),T('When the Rasi lords are mutual friends or the rest of the relationship chart is strong, the flag is treated as a manageable adjustment pattern instead of a marriage rejection.','ராசி அதிபதிகள் நட்பில் இருந்தாலோ அல்லது முழு உறவு ஜாதக ஆதாரம் வலுவாக இருந்தாலோ, இதை திருமண நிராகரிப்பாக அல்லாமல் கையாளக்கூடிய ஒத்திசைவு pattern ஆகப் பார்க்க வேண்டும்.')],'dosha');html+=mmV216Page(T('Kendradhipatya — Bride functional-lord refinement','கேந்திராதிபத்தியம் — பெண் functional-lord refinement'),[fmt(bk),T('A natural benefic owning a Kendra can become more functionally neutral and may deliver results through responsibility, placement and Dasha strength rather than simply giving easy benefic results. This is a refinement, not a stand-alone marriage dosha.','இயற்கை சுபகிரகம் கேந்திர பாவத்தை நடத்தும்போது அதன் சுபபலன் நேரடியாக எளிதில் வராமல், placement, பலம், பொறுப்பு மற்றும் தசைச் செயல்பாட்டின் மூலம் வெளிப்படலாம். இது தனி திருமண தோஷம் அல்ல; functional refinement.')],'dosha');html+=mmV216Page(T('Kendradhipatya — Groom functional-lord refinement','கேந்திராதிபத்தியம் — ஆண் functional-lord refinement'),[fmt(gk),T('During the relevant planet periods, judge the actual house it occupies, dignity, aspects and D9 support. Strong support can turn the same lordship into constructive responsibility rather than loss.','சம்பந்தப்பட்ட கிரக தசையில் அது இருக்கும் பாவம், ராசி பலம், பார்வை மற்றும் D9 ஆதரவை பார்க்க வேண்டும். நல்ல ஆதரவு இருந்தால் இதே அதிபத்தியம் இழப்பாக அல்லாமல் பயனுள்ள பொறுப்பாக வெளிப்படலாம்.')],'dosha');return html}


function mmFrontPoruthamPanel(pr){
 const rows=(pr?.rows||[]).map(([name,ok,detail])=>`<div class="mm-front-porutham-row"><b>${esc(name)}</b><strong class="${ok?'ok':'no'}">${ok?T('MATCH','பொருந்தும்'):T('NO MATCH','பொருந்தாது')}</strong>${detail?`<small>${esc(detail)}</small>`:''}</div>`).join('');
 return `<section class="mm-person-result mm-front-porutham"><h3>${T('10 Nakshatra / Tamil Porutham Results','நட்சத்திர பத்து பொருத்த முடிவுகள்')}</h3><p class="mm-porutham-score">${T('Total','மொத்தம்')}: ${pr.score}/10</p><div class="mm-front-porutham-grid">${rows}</div><div class="mm-front-pair-only mm-front-summary-note"><b>${T('Nadi — additional traditional review','நாடி — கூடுதல் பாரம்பரிய ஆய்வு')}:</b> ${pr.nadi.ok?T('Different Nadi / no same-Nadi flag','வேறு நாடி / ஒரே நாடி தோஷக் குறி இல்லை'):T('Same Nadi — cancellation / full-chart review required','ஒரே நாடி — தோஷ விலக்கு / முழு ஜாதக ஆய்வு தேவை')} · ${esc(pr.nadi.detail)}</div>${mmNakshatraHumanReading(pr)}</section>`;
}
function mmFrontState(kind,x){
 const ta=lang()==='ta';
 if(kind==='kuja'){
  if(!x||x.state==='none')return {v:0,text:T('Not Present','இல்லை'),cls:'ok'};
  if(x.state==='cancelled')return {v:0,text:T('Present — fully balanced / Vilakku','உள்ளது — முழு சமநிலை / விலக்கு'),cls:'ok'};
  if(x.state==='partial')return {v:1,text:T('Present — partially balanced','உள்ளது — பகுதி சமநிலை'),cls:'warn'};
  if(x.state==='consult'||x.state==='strong')return {v:2,text:T('Present — strong / review','உள்ளது — வலுவானது / ஆய்வு'),cls:'no'};
  return {v:1,text:T('Present','உள்ளது'),cls:'warn'};
 }
 if(kind==='naga'){
  if(!x||x.state==='unknown')return {v:0,text:T('Insufficient data','தரவு போதவில்லை'),cls:'warn'};
  if(x.state==='none')return {v:0,text:T('Not Present','இல்லை'),cls:'ok'};
  if(x.state==='balanced')return {v:0,text:T('Initial indicators offset — residual 0','ஆரம்பக் குறிகள் குறைந்தன — மீதி 0'),cls:'ok'};
  if(x.state==='mild')return {v:1,text:T('Low residual indication','குறைந்த மீதத் தாக்கம்'),cls:'warn'};
  if(x.state==='strong')return {v:2,text:T('Present — strong','உள்ளது — வலுவானது'),cls:'no'};
  return {v:1,text:T('Moderate residual indication','மிதமான மீதத் தாக்கம்'),cls:'warn'};
 }
 if(kind==='kala')return x?.present?{v:1,text:T('Present','உள்ளது'),cls:'warn'}:{v:0,text:T('Not Present','இல்லை'),cls:'ok'};
 if(!x||x.state==='none'||x.level===0)return {v:0,text:T('Not Present','இல்லை'),cls:'ok'};
 if(x.state==='mitigated'||x.state==='moderated')return {v:0,text:T('Present — balanced / Vilakku','உள்ளது — சமநிலை / விலக்கு'),cls:'ok'};
 if(x.state==='strong'||x.state==='complex')return {v:2,text:T('Present — strong / review','உள்ளது — வலுவானது / ஆய்வு'),cls:'no'};
 return {v:1,text:T('Present','உள்ளது'),cls:'warn'};
}
function mmFrontDoshaCard(title,groom,bride,balanceText){
 return `<article class="mm-front-dosha-card"><h4>${esc(title)}</h4><div class="mm-front-dosha-status"><b>${T('Groom','ஆண்')}</b><strong class="${groom.cls}">${esc(groom.text)}</strong></div><div class="mm-front-dosha-status"><b>${T('Bride','பெண்')}</b><strong class="${bride.cls}">${esc(bride.text)}</strong></div><div class="mm-front-dosha-status"><b>${T('Balance','சமநிலை')}</b><strong class="${balanceText.cls}">${esc(balanceText.text)}</strong></div></article>`;
}
function mmFrontDoshaSummaryPanel(b,g,pr,ks,sync,ds){
 const B=structuredLagnaDoshas(b),G=structuredLagnaDoshas(g),kb=kujaVilakku(ks.B,ks.G),kg=kujaVilakku(ks.G,ks.B),bk=kalaSarpaAssessment(b),gk=kalaSarpaAssessment(g),nb=nagaDoshaAssessment(b),ng=nagaDoshaAssessment(g),rows=[];
 const balance=(a,z,forced=null)=>{if(forced!=null)return forced?{text:T('Balanced / comparable','சமநிலை உள்ளது'),cls:'ok'}:{text:T('Unequal — review','சமமில்லை — ஆய்வு'),cls:'no'};const d=Math.abs((a?.v||0)-(z?.v||0));return d===0?{text:T('Equal / balanced','சமநிலை'),cls:'ok'}:d===1?{text:T('Near balance — review','நெருங்கிய சமநிலை — ஆய்வு'),cls:'warn'}:{text:T('Unequal — review','சமமில்லை — ஆய்வு'),cls:'no'}};
 const add=(en,ta,kind,gx,bx,forced)=>{const gs=mmFrontState(kind,gx),bs=mmFrontState(kind,bx);rows.push(mmFrontDoshaCard(T(en,ta),gs,bs,balance(gs,bs,forced)))};
 add('Kuja / Mars Dosha','செவ்வாய் / குஜ தோஷம்','kuja',kg,kb,ks.balanced);
 add('Rahu Dosha / nodal pressure','ராகு தோஷ / node அழுத்தம்','structured',G.rahu,B.rahu);
 add('Ketu Dosha / nodal pressure','கேது தோஷ / node அழுத்தம்','structured',G.ketu,B.ketu);
 add('Mangalya Dosha indicators','மாங்கல்ய தோஷக் குறியீடுகள்','structured',G.mangalya,B.mangalya);
 add('Putra Dosha indicators','புத்திர தோஷக் குறியீடுகள்','structured',G.putra,B.putra);
 add('Sukra / Venus affliction','சுக்கிர தோஷக் குறியீடுகள்','structured',G.sukra,B.sukra);
 add('Kalathra / 7th-house Dosha','களத்திர / 7-ஆம் பாவ தோஷம்','structured',G.kalathra,B.kalathra);
 add('Kala Sarpa Yoga','கால சர்ப்ப யோகம்','kala',gk,bk);
 add('Naga / Sarpa Dosha','நாக / சர்ப்ப தோஷம்','naga',ng,nb);
 const sh=mmShashtashtaka(pr),kbd=mmKendraAdhipatya(b),kgd=mmKendraAdhipatya(g);
 rows.push(mmFrontDoshaCard(T('Kendradhipatya functional-lord condition','கேந்திராதிபத்திய functional-lord நிலை'),{v:kgd.present?1:0,text:kgd.label,cls:kgd.present?'warn':'ok'},{v:kbd.present?1:0,text:kbd.label,cls:kbd.present?'warn':'ok'},(kgd.present===kbd.present?{text:T('Comparable','ஒப்பிடத்தக்க சமநிலை'),cls:'ok'}:{text:T('Unequal — review in Dasha','சமமில்லை — தசையில் ஆய்வு'),cls:'warn'})));
 const nv=nadiVilakku(pr,b,g),rj=rajjuVilakku(pr),ppB=papasamyam(b),ppG=papasamyam(g),ppDiff=Math.abs(ppB.total-ppG.total),sev=syncSeverity(sync);
 const pair=(name,value,cls='warn')=>`<article class="mm-front-dosha-card mm-front-pair-only"><h4>${esc(name)}</h4><div class="mm-front-dosha-status"><b>${T('Couple','இருவர்')}</b><strong class="${cls}">${esc(value)}</strong></div></article>`;
 const compare=(name,groomText,brideText,balanceText,cls='ok')=>`<article class="mm-front-dosha-card"><h4>${esc(name)}</h4><div class="mm-front-dosha-status"><b>${T('Groom','ஆண்')}</b><strong>${esc(groomText)}</strong></div><div class="mm-front-dosha-status"><b>${T('Bride','பெண்')}</b><strong>${esc(brideText)}</strong></div><div class="mm-front-dosha-status"><b>${T('Balance','சமநிலை')}</b><strong class="${cls}">${esc(balanceText)}</strong></div></article>`;
 const nadiName=i=>T(NADI[i],{Adi:'ஆதி',Madhya:'மத்திய',Antya:'அந்த்ய'}[NADI[i]]||NADI[i]),rajjuName=i=>RAJJU_NAME[RAJJU[i]]?.[lang()==='ta'?1:0]||String(RAJJU[i]||'—');
 const nadiTxt=['none','mitigated'].includes(nv.state)?T('No same-Nadi dosha / balanced','ஒரே நாடி தோஷம் இல்லை / சமநிலை'):T('Same Nadi — full-chart review required','ஒரே நாடி — முழு ஜாதக ஆய்வு தேவை');
 const rajjuTxt=rj.state==='none'?T('Balanced / exception cleared','சமநிலை / விதிவிலக்கால் நீங்கியது'):T('Present — exception/protection review required','உள்ளது — விலக்கு/பாதுகாப்பு ஆய்வு தேவை');
 const papaTxt=ppDiff<=.75?T('Balanced','சமநிலை'):ppDiff<=1.5?T('Moderate difference — review','மிதமான வேறுபாடு — ஆய்வு'):T('Unequal — consultation review','சமமில்லை — ஆலோசனை ஆய்வு');
 const syncTxt=(sev.status.Mars.overlap||sev.status.Rahu.overlap)?T('Dosha-linked periods overlap — review timing','தோஷம் சார்ந்த தசை காலங்கள் ஒரே நேரத்தில் — கால ஆய்வு தேவை'):(sev.status.Mars.near||sev.status.Rahu.near)?T('Dosha-linked periods are near — timing review','தோஷம் சார்ந்த தசை காலங்கள் அருகில் — கால ஆய்வு'):T('No major near/overlap flag','முக்கிய அருகாமை / overlap குறி இல்லை');
 const shCard=compare(T('Shashtashtaka / 6–8 Rasi Dosha','ஷஷ்டாஷ்டக / 6–8 ராசி தோஷம்'),sign(pr.rasi?.gr??0),sign(pr.rasi?.br??0),sh.text,sh.present?(sh.mitigated?'warn':'no'):'ok');
 const nadiCard=compare(T('Nadi Dosha','நாடி தோஷம்'),nadiName(pr.star.gi),nadiName(pr.star.bi),nadiTxt,['none','mitigated'].includes(nv.state)?'ok':'no');
 const rajjuCard=compare(T('Rajju Dosha','ரஜ்ஜு தோஷம்'),rajjuName(pr.star.gi),rajjuName(pr.star.bi),rajjuTxt,rj.state==='none'?'ok':'no');
 const papaCard=compare(T('Papasamyam / malefic balance','பாபசாம்யம் / பாப கிரக சமநிலை'),ppG.total.toFixed(2),ppB.total.toFixed(2),papaTxt,ppDiff<=.75?'ok':ppDiff<=1.5?'warn':'no');
 return `<section class="mm-person-result mm-front-dosha-summary"><h3>${T('Complete Dosha Status — Groom, Bride & Balance','முழு தோஷ நிலை — ஆண், பெண் & சமநிலை')}</h3><p class="mm-front-summary-note">${T('This opening list is a quick status index. “Present” means the calculation found the stated condition; “balanced/Vilakku” means protection or cancellation factors reduce it. Detailed reasons, timing and remedies follow later in the report.','இந்த தொடக்கப் பட்டியல் விரைவான நிலைச் சுருக்கம். “உள்ளது” என்பது அந்த தோஷக் குறியீடு கணக்கில் கண்டறியப்பட்டது என்பதைக் குறிக்கும்; “சமநிலை/விலக்கு” என்பது பாதுகாப்பு அல்லது தோஷ விலக்கு காரணிகள் அதை குறைக்கின்றன என்பதைக் குறிக்கும். விரிவான காரணம், காலம் மற்றும் பரிகாரம் பின்னர் அறிக்கையில் வரும்.')}</p><div class="mm-front-dosha-list">${rows.join('')}${shCard}${nadiCard}${rajjuCard}${papaCard}${pair(T('Dasha–Dosha timing balance','தசா–தோஷ கால சமநிலை'),syncTxt,(sev.status.Mars.overlap||sev.status.Rahu.overlap)?'no':(sev.status.Mars.near||sev.status.Rahu.near)?'warn':'ok')}</div></section>`;
}

